
function getDepartmentSpecialty(deptName) {
  if (!deptName) return 'lamsang';
  const clean = deptName.trim().toLowerCase();
  if (clean.includes('gây mê') || clean.includes('gay me') || clean.includes('phòng mổ') || clean.includes('phong mo')) return 'gayme';
  if (clean.includes('nội soi') || clean.includes('noi soi')) return 'noisoi';
  if (clean.includes('khám bệnh') || clean.includes('kham benh')) return 'khambenh';
  if (clean.includes('chẩn đoán hình ảnh') || clean.includes('chan doan hinh anh') || clean.includes('cđha') || clean.includes('cdha') || clean.includes('hình ảnh')) return 'cdha';
  if (clean.includes('phục hồi chức năng') || clean.includes('phuc hoi') || clean.includes('vltl') || clean.includes('phcn')) return 'vltl_phcn';
  if (clean.includes('xét nghiệm') || clean.includes('xet nghiem') || clean.includes('shpt') || clean.includes('sinh học phân tử')) return 'xetnghiem';
  if (typeof DEPARTMENT_CONFIG !== 'undefined') {
    const found = DEPARTMENT_CONFIG.find(d => d.dept && d.dept.toLowerCase() === clean);
    if (found && found.specialty && found.specialty !== 'all') return found.specialty;
  }
  return 'lamsang';
}

function normalizeDepartmentName(dept) {
  if (!dept) return '';
  let str = dept.toString()
    .toLowerCase()
    .trim()
    .replace(/^(khoa|đơn vị|trung tâm|ban|phòng)\s+/i, '')
    .replace(/[\s\-_]/g, '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  const aliases = {
    'ctch': 'chanthuongchinhhinh',
    'chanthuong': 'chanthuongchinhhinh',
    'chinhhinh': 'chanthuongchinhhinh',
    'gmhs': 'gaymehoisuc',
    'gayme': 'gaymehoisuc',
    'cdha': 'chandoanhinhanh',
    'phcn': 'phuchoichucnang',
    'vltl': 'phuchoichucnang',
    'phcnvltl': 'phuchoichucnang',
    'vltlphcn': 'phuchoichucnang',
    'ksnk': 'kiemsoatnhiemkhuan',
    'shpt': 'sinhhocphantu',
    'khambenh': 'khambenh',
    'dieuduong': 'dieuduong',
    'bandieuduong': 'dieuduong'
  };

  return aliases[str] || str;
}

function isSameDepartment(deptA, deptB) {
  if (!deptA || !deptB) return false;
  if (deptA === deptB) return true;
  return normalizeDepartmentName(deptA) === normalizeDepartmentName(deptB);
}

