// Cấu hình font chữ tiếng Việt mặc định cho Chart.js
if (typeof Chart !== 'undefined') {
  Chart.defaults.font.family = "'Be Vietnam Pro', 'Segoe UI', Arial, Tahoma, sans-serif";
}

/**
 * Hàm phòng vệ chống XSS (Cross-Site Scripting): Mã hóa an toàn mọi dữ liệu người dùng trước khi hiển thị trong HTML
 */
function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

/**
 * Lấy Base URL của Backend API linh hoạt (tương thích Vercel Serverless & Local)
 */
function getBackendApiUrl() {
  if (typeof window !== 'undefined' && window.API_BASE_URL) return window.API_BASE_URL;
  if (typeof window !== 'undefined' && window.location && window.location.origin && window.location.origin.startsWith('http')) {
    return `${window.location.origin}/api`;
  }
  return 'http://localhost:5000/api';
}

/**
 * Lấy Header Authorization mang theo Bearer Token cho các API Backend
 */
function getAuthHeader() {
  let token = null;
  if (typeof getAuthToken === 'function') token = getAuthToken();
  if (!token && typeof sessionStorage !== 'undefined') token = sessionStorage.getItem('umc_auth_token');
  return token ? { 'Authorization': `Bearer ${token}` } : {};
}

