function sanitizeUserForStorage(user) {
  if (!user) return null;
  const { password, ...clean } = user;
  return clean;
}


function resetAllSubmissionsData() {
  openConfirmModal({
    title: 'Xóa Toàn Bộ Dữ Liệu Hồ Sơ (Reset Trắng)',
    icon: '🗑️',
    message: 'Bạn có chắc chắn muốn <strong>xóa toàn bộ hồ sơ đánh giá và lịch sử phê duyệt</strong> trên hệ thống để nhập lại từ đầu? <br><br><span class="text-rose-600 font-bold text-xs">⚠️ Hành động này sẽ đưa toàn bộ hồ sơ các khoa về trạng thái trống ban đầu (Tài khoản và Phân quyền vẫn giữ nguyên).</span>',
    btnText: 'Xác Nhận Xóa Sạch & Reset',
    btnClass: 'bg-rose-700 hover:bg-rose-800',
    onConfirm: () => {
      APP_STATE.submissions = [];
      localStorage.setItem('umc_submissions', JSON.stringify([]));
      if (typeof renderAllViews === 'function') renderAllViews();
      else {
        if (typeof renderAssessmentTab === 'function') renderAssessmentTab();
        if (typeof renderApprovalsTab === 'function') renderApprovalsTab();
      if (typeof renderMailboxNotifications === 'function') renderMailboxNotifications();
      if (typeof renderAssessmentTab === 'function') renderAssessmentTab();
        if (typeof renderReportsTab === 'function') renderReportsTab();
      }
      showToast('✨ Đã xóa sạch toàn bộ dữ liệu hồ sơ! Hệ thống sẵn sàng để bạn nhập dữ liệu giả định mới.', 'success');
    }
  });
}
window.resetAllSubmissionsData = resetAllSubmissionsData;

function initStorage() {
  const CURRENT_SYSTEM_VERSION = 'umc_v22_production_clean_2026';
  const cleanUsers = (INITIAL_USERS || []).map(sanitizeUserForStorage);
  localStorage.setItem('umc_users', JSON.stringify(cleanUsers));
  APP_STATE.users = cleanUsers;

  let storedSubs = [];
  try {
    storedSubs = JSON.parse(localStorage.getItem('umc_submissions')) || [];
  } catch(e) {
    storedSubs = [];
  }

  // Giữ lại các hồ sơ thực tế do người dùng nhập
  storedSubs = storedSubs.filter(s => s && (
    (s.totalScore !== undefined && s.totalScore > 0) || 
    (s.scores && Object.values(s.scores).some(v => v > 0)) ||
    (s.status && s.status !== 'draft')
  ));
  APP_STATE.submissions = storedSubs;
  localStorage.setItem('umc_submissions', JSON.stringify(storedSubs));

  try {
    APP_STATE.userPortfolios = JSON.parse(localStorage.getItem('umc_user_portfolios') || '{}');
  } catch(e) {
    APP_STATE.userPortfolios = {};
  }

  // Kích hoạt đồng bộ Cloud ngầm
  if (typeof window !== 'undefined') {
    setTimeout(syncWithCloudOnStartup, 600);
  }
}

function saveStorage() {
  const safeUsers = (APP_STATE.users || []).map(sanitizeUserForStorage);
  localStorage.setItem('umc_users', JSON.stringify(safeUsers));
  localStorage.setItem('umc_submissions', JSON.stringify(APP_STATE.submissions));
  scheduleCloudSync();
}

// =========================================================================
// CLOUD SYNC ADAPTER (SUPABASE & BACKEND HYBRID SYNC ENGINE)
// =========================================================================

let _cloudSyncDebounceTimer = null;

function updateCloudSyncBadge(state, mode = 'direct') {
  const dot = document.getElementById('cloud-sync-dot');
  const text = document.getElementById('cloud-sync-text');
  const container = document.getElementById('cloud-sync-container');
  if (!dot || !text) return;

  if (state === 'connected') {
    dot.className = 'w-2.5 h-2.5 rounded-full bg-emerald-400 shadow-xs';
    text.textContent = mode === 'backend' ? 'Backend (5000)' : 'Supabase Cloud';
    if (container) container.title = `Đã kết nối thành công với ${mode === 'backend' ? 'Backend Localhost API (Port 5000)' : 'Supabase Cloud Database (PostgreSQL)'}`;
  } else if (state === 'checking') {
    dot.className = 'w-2.5 h-2.5 rounded-full bg-blue-400 animate-pulse';
    text.textContent = 'Đang kết nối...';
  } else {
    dot.className = 'w-2.5 h-2.5 rounded-full bg-amber-400';
    text.textContent = 'Chế độ Offline';
    if (container) container.title = 'Chế độ Offline: Dữ liệu đang được lưu an toàn trong trình duyệt (localStorage).';
  }
}

/**
 * Đồng bộ hai chiều ngầm với Cloud khi khởi động ứng dụng
 */
async function syncWithCloudOnStartup() {
  if (typeof checkCloudConnection !== 'function') return;

  try {
    updateCloudSyncBadge('checking');
    const conn = await checkCloudConnection();
    if (!conn.online) {
      updateCloudSyncBadge('offline');
      return;
    }

    updateCloudSyncBadge('connected', conn.mode);

    // 1. Tải hồ sơ đánh giá từ Cloud
    if (typeof cloudFetchSubmissions === 'function') {
      const cloudSubs = await cloudFetchSubmissions();
      if (cloudSubs && Array.isArray(cloudSubs) && cloudSubs.length > 0) {
        cloudSubs.forEach(cSub => {
          const localIdx = (APP_STATE.submissions || []).findIndex(s => s.id === cSub.id);
          if (localIdx !== -1) {
            const localTime = new Date(APP_STATE.submissions[localIdx].updatedAt || 0).getTime();
            const cloudTime = new Date(cSub.updatedAt || 0).getTime();
            if (cloudTime >= localTime) {
              APP_STATE.submissions[localIdx] = cSub;
            }
          } else {
            APP_STATE.submissions.push(cSub);
          }
        });
        localStorage.setItem('umc_submissions', JSON.stringify(APP_STATE.submissions));
      } else if (APP_STATE.submissions && APP_STATE.submissions.length > 0) {
        const firstSub = APP_STATE.submissions[0];
        if (typeof cloudSyncSubmission === 'function') cloudSyncSubmission(firstSub);
      }
    }

    // 2. Tải danh sách nhân sự từ Cloud
    if (typeof cloudFetchUsers === 'function') {
      const cloudUsers = await cloudFetchUsers();
      if (cloudUsers && Array.isArray(cloudUsers) && cloudUsers.length > 0) {
        cloudUsers.forEach(cUser => {
          const localIdx = (APP_STATE.users || []).findIndex(u => u.id === cUser.id);
          if (localIdx !== -1) {
            APP_STATE.users[localIdx] = { ...APP_STATE.users[localIdx], ...cUser };
          } else {
            APP_STATE.users.push(cUser);
          }
        });
        localStorage.setItem('umc_users', JSON.stringify(APP_STATE.users));
      } else if (typeof cloudSyncUsers === 'function' && APP_STATE.users && APP_STATE.users.length > 0) {
        cloudSyncUsers(APP_STATE.users);
      }
    }

    // Cập nhật lại view nếu người dùng đã đăng nhập
    if (APP_STATE.currentUser) {
      const refreshed = (APP_STATE.users || []).find(u => u.id === APP_STATE.currentUser.id);
      if (refreshed) APP_STATE.currentUser = refreshed;
      if (typeof renderAllViews === 'function') renderAllViews();
    }
  } catch (err) {
    console.warn('Lỗi đồng bộ Cloud khởi động:', err);
    updateCloudSyncBadge('offline');
  }
}

/**
 * Đồng bộ ngầm lên Cloud khi có thay đổi dữ liệu (debounced)
 */
function scheduleCloudSync() {
  if (_cloudSyncDebounceTimer) clearTimeout(_cloudSyncDebounceTimer);

  _cloudSyncDebounceTimer = setTimeout(async () => {
    try {
      if (typeof checkCloudConnection !== 'function') return;
      const conn = await checkCloudConnection();
      if (!conn.online) {
        updateCloudSyncBadge('offline');
        return;
      }
      updateCloudSyncBadge('connected', conn.mode);

      if (APP_STATE.currentUser && typeof cloudSyncUsers === 'function') {
        cloudSyncUsers([APP_STATE.currentUser]);
      }

      if (APP_STATE.currentUser && typeof cloudSyncSubmission === 'function') {
        const sub = getUserSubmission(APP_STATE.currentUser.id);
        if (sub) {
          sub.updatedAt = new Date().toISOString();
          cloudSyncSubmission(sub);
        }
      }
    } catch (e) {
      console.warn('Lỗi đồng bộ ngầm:', e);
    }
  }, 1200);
}

/**
 * Hàm đồng bộ thủ công khi người dùng bấm nút 🔄 trên Header
 */
async function manualSyncWithCloud() {
  if (typeof checkCloudConnection !== 'function') {
    showToast('Chưa nạp module kết nối Cloud!', 'warning');
    return;
  }

  showToast('Đang kết nối và đồng bộ với Supabase Cloud...', 'info');
  updateCloudSyncBadge('checking');

  try {
    const conn = await checkCloudConnection();
    if (!conn.online) {
      updateCloudSyncBadge('offline');
      showToast('Không thể kết nối đến Supabase Cloud. Đang hoạt động ở chế độ Offline (localStorage)!', 'warning');
      return;
    }

    updateCloudSyncBadge('connected', conn.mode);

    if (APP_STATE.currentUser && typeof cloudSyncUsers === 'function') {
      await cloudSyncUsers([APP_STATE.currentUser]);
    }

    if (APP_STATE.currentUser && typeof cloudSyncSubmission === 'function') {
      const sub = getUserSubmission(APP_STATE.currentUser.id);
      if (sub) {
        sub.updatedAt = new Date().toISOString();
        await cloudSyncSubmission(sub);
      }
    }

    if (typeof cloudFetchSubmissions === 'function') {
      const subs = await cloudFetchSubmissions();
      if (subs && subs.length > 0) {
        subs.forEach(cSub => {
          const idx = (APP_STATE.submissions || []).findIndex(s => s.id === cSub.id);
          if (idx !== -1) APP_STATE.submissions[idx] = cSub;
          else APP_STATE.submissions.push(cSub);
        });
        localStorage.setItem('umc_submissions', JSON.stringify(APP_STATE.submissions));
      }
    }

    if (typeof renderAllViews === 'function') renderAllViews();
    showToast(`Đồng bộ thành công qua ${conn.mode === 'backend' ? 'Backend Localhost (Port 5000)' : 'Supabase Cloud (PostgreSQL)'}! ☁️🎉`, 'success');
  } catch (err) {
    console.error('Lỗi đồng bộ thủ công:', err);
    updateCloudSyncBadge('offline');
    showToast('Lỗi đồng bộ: ' + err.message, 'error');
  }
}


// Thông báo Toast
function showToast(message, type = 'info') {
  const container = document.getElementById('toast-container') || document.body;
  const toast = document.createElement('div');
  const bg = type === 'success' ? 'bg-emerald-600' : type === 'error' ? 'bg-rose-600' : type === 'warning' ? 'bg-amber-600' : 'bg-blue-600';
  toast.className = `fixed bottom-5 right-5 z-50 text-white px-5 py-3 rounded-xl shadow-2xl flex items-center gap-3 animate-fade-in ${bg} text-xs font-semibold border border-white/20`;
  toast.innerHTML = `
    <span>${type === 'success' ? '✅' : type === 'error' ? '⚠️' : type === 'warning' ? '🔔' : 'ℹ️'}</span>
    <span>${message}</span>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transition = 'opacity 0.3s ease';
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}


// =========================================================================
/**
 * Hiển thị thông báo lỗi đăng nhập trực quan và viền đỏ cho trường nhập sai (tên đăng nhập hoặc mật khẩu)
 */
function showLoginError(field, message) {
  const alertEl = document.getElementById('login-error-alert');
  const titleEl = document.getElementById('login-error-title');
  const descEl = document.getElementById('login-error-desc');
  const usernameInput = document.getElementById('login-username');
  const passwordInput = document.getElementById('login-password');

  if (alertEl && descEl) {
    alertEl.classList.remove('hidden');
    descEl.textContent = message;

    if (field === 'username') {
      if (titleEl) titleEl.textContent = '❌ Sai tên đăng nhập / MSNV:';
      if (usernameInput) {
        usernameInput.classList.add('border-rose-500', 'bg-rose-50/60', 'ring-2', 'ring-rose-200');
        usernameInput.focus();
        usernameInput.select();
      }
      if (passwordInput) {
        passwordInput.classList.remove('border-rose-500', 'bg-rose-50/60', 'ring-2', 'ring-rose-200');
      }
    } else if (field === 'password') {
      if (titleEl) titleEl.textContent = '❌ Sai mật khẩu:';
      if (passwordInput) {
        passwordInput.classList.add('border-rose-500', 'bg-rose-50/60', 'ring-2', 'ring-rose-200');
        passwordInput.focus();
        passwordInput.select();
      }
      if (usernameInput) {
        usernameInput.classList.remove('border-rose-500', 'bg-rose-50/60', 'ring-2', 'ring-rose-200');
      }
    } else {
      if (titleEl) titleEl.textContent = '⚠️ Đăng nhập không thành công:';
    }
  }
  showToast(message, 'error');
}

/**
 * Xóa trạng thái cảnh báo lỗi khi người dùng bắt đầu gõ lại
 */
function clearLoginError() {
  const alertEl = document.getElementById('login-error-alert');
  const usernameInput = document.getElementById('login-username');
  const passwordInput = document.getElementById('login-password');

  if (alertEl) alertEl.classList.add('hidden');
  if (usernameInput) usernameInput.classList.remove('border-rose-500', 'bg-rose-50/60', 'ring-2', 'ring-rose-200');
  if (passwordInput) passwordInput.classList.remove('border-rose-500', 'bg-rose-50/60', 'ring-2', 'ring-rose-200');
}

async function handleUserLogin(event) {
  if (event) event.preventDefault();
  const usernameInput = document.getElementById('login-username');
  const passwordInput = document.getElementById('login-password');
  const btnLogin = document.getElementById('btn-login-submit');
  const btnText = document.getElementById('btn-login-text');
  
  const username = usernameInput ? usernameInput.value.trim() : '';
  const password = passwordInput ? passwordInput.value : '';
  
  if (!username) {
    showToast('Vui lòng nhập Tên đăng nhập / MSNV / Email!', 'warning');
    if (typeof showLoginError === 'function') {
      showLoginError('username', 'Vui lòng nhập Tên đăng nhập / MSNV / Email!');
    }
    if (usernameInput) usernameInput.focus();
    return false;
  }
  if (!password || !password.trim()) {
    showToast('Vui lòng nhập Mật khẩu!', 'warning');
    if (typeof showLoginError === 'function') {
      showLoginError('password', 'Vui lòng nhập Mật khẩu để đăng nhập vào hệ thống!');
    }
    if (passwordInput) passwordInput.focus();
    return false;
  }

  if (btnLogin) btnLogin.disabled = true;
  if (btnText) btnText.textContent = 'ĐANG XÁC THỰC...';

  try {
    return await login(username, password);
  } finally {
    if (btnLogin) btnLogin.disabled = false;
    if (btnText) btnText.textContent = 'ĐĂNG NHẬP HỆ THỐNG';
  }
}

async function quickLoginAs(userId) {
  const user = (APP_STATE.users || []).find(u => u.id === userId);
  if (!user) {
    showToast(`Không tìm thấy tài khoản ${userId}!`, 'error');
    return;
  }
  const usernameInput = document.getElementById('login-username');
  const passwordInput = document.getElementById('login-password');
  if (usernameInput) usernameInput.value = user.userName || user.msnv || user.id;
  if (passwordInput) passwordInput.value = '123';
  showToast(`Chế độ kiểm thử: Đang đăng nhập tài khoản "${user.fullName}"...`, 'info');
  await login(user.userName || user.id, '123');
}

async function switchUserRole(userId) {
  const user = (APP_STATE.users || []).find(u => u.id === userId);
  if (!user) return;
  await login(user.userName || user.id, '123');
}

function handleUserLogout() {
  if (typeof apiLogout === 'function') apiLogout();
  if (typeof sessionStorage !== 'undefined') {
    sessionStorage.removeItem('umc_auth_token');
    sessionStorage.removeItem('umc_auth_user');
  }
  APP_STATE.currentUser = null;
  APP_STATE.isLoggedIn = false;
  
  const loginScreen = document.getElementById('login-screen');
  const mainWrapper = document.getElementById('main-app-wrapper');
  
  if (loginScreen) loginScreen.classList.remove('hidden');
  if (mainWrapper) mainWrapper.classList.add('hidden');
  
  const passwordInput = document.getElementById('login-password');
  if (passwordInput) passwordInput.value = '';
  
  showToast('Đã đăng xuất khỏi hệ thống an toàn.', 'info');
}

function toggleDemoAccountsPanel() {
  const panel = document.getElementById('demo-accounts-panel');
  const btn = document.getElementById('btn-toggle-demo');
  if (panel) {
    const isHidden = panel.classList.contains('hidden');
    if (isHidden) {
      panel.classList.remove('hidden');
      if (btn) btn.textContent = '[Ẩn tài khoản mẫu ▲]';
    } else {
      panel.classList.add('hidden');
      if (btn) btn.textContent = '[Hiển thị tài khoản mẫu ▼]';
    }
  }
}

function togglePasswordVisibility() {
  const pwd = document.getElementById('login-password');
  const btn = document.getElementById('btn-toggle-password');
  const eyeOpen = document.getElementById('eye-icon-open');
  const eyeClosed = document.getElementById('eye-icon-closed');
  if (!pwd) return;
  const isPwd = pwd.type === 'password';
  pwd.type = isPwd ? 'text' : 'password';
  if (eyeOpen && eyeClosed) {
    if (isPwd) {
      eyeOpen.classList.add('hidden');
      eyeClosed.classList.remove('hidden');
      if (btn) btn.setAttribute('title', 'Ẩn mật khẩu');
    } else {
      eyeOpen.classList.remove('hidden');
      eyeClosed.classList.add('hidden');
      if (btn) btn.setAttribute('title', 'Hiển thị mật khẩu');
    }
  }
}

// =========================================================================
// KHÔI PHỤC MẬT KHẨU QUA EMAIL UMC CỦA NHÂN VIÊN
// =========================================================================
let CURRENT_RESET_SESSION = null;

function openForgotPasswordModal() {
  const modal = document.getElementById('modal-forgot-password');
  const loginUserInput = document.getElementById('login-username');
  const forgotInput = document.getElementById('forgot-identifier');
  
  if (forgotInput) {
    if (loginUserInput && loginUserInput.value.trim()) {
      forgotInput.value = loginUserInput.value.trim();
    } else {
      forgotInput.value = '';
    }
  }

  const step1 = document.getElementById('forgot-step-1');
  const step2 = document.getElementById('forgot-step-2');
  const step3 = document.getElementById('forgot-step-3');
  if (step1) step1.classList.remove('hidden');
  if (step2) step2.classList.add('hidden');
  if (step3) step3.classList.add('hidden');

  if (modal) {
    modal.classList.remove('hidden');
    if (forgotInput) forgotInput.focus();
  }
}

function closeForgotPasswordModal() {
  const modal = document.getElementById('modal-forgot-password');
  if (modal) modal.classList.add('hidden');
}

function backToStep1Forgot() {
  const step1 = document.getElementById('forgot-step-1');
  const step2 = document.getElementById('forgot-step-2');
  const step3 = document.getElementById('forgot-step-3');
  if (step1) step1.classList.remove('hidden');
  if (step2) step2.classList.add('hidden');
  if (step3) step3.classList.add('hidden');
  const forgotInput = document.getElementById('forgot-identifier');
  if (forgotInput) forgotInput.focus();
}

function autoFillOtp(code) {
  const cleanCode = String(code || '').replace(/\D/g, '').trim();
  const input = document.getElementById('forgot-otp-input');
  if (input && cleanCode) {
    input.value = cleanCode;
    showToast(`Đã tự động điền mã xác thực OTP: ${cleanCode}`, 'info');
    const newPwd = document.getElementById('forgot-new-password');
    if (newPwd) newPwd.focus();
  }
}

async function handleSendResetEmail(event) {
  if (event) event.preventDefault();
  const identifierInput = document.getElementById('forgot-identifier');
  const btn = document.getElementById('btn-send-reset-email');
  const btnText = document.getElementById('btn-send-reset-text');

  const identifier = identifierInput ? identifierInput.value.trim() : '';
  if (!identifier) {
    showToast('Vui lòng nhập Tên đăng nhập, MSNV hoặc Email UMC của bạn!', 'warning');
    if (identifierInput) identifierInput.focus();
    return false;
  }

  if (btn) btn.disabled = true;
  if (btnText) btnText.textContent = 'ĐANG TRA CỨU & GỬI THƯ...';

  try {
    let email = null;
    let fullName = null;
    let msnv = null;
    let userName = null;
    let otp = null;
    let userObj = null;

    // 1. Ưu tiên gọi Backend API nếu backend khả dụng
    if (typeof apiForgotPassword === 'function') {
      try {
        const res = await apiForgotPassword(identifier);
        if (res && res.success) {
          email = res.maskedEmail || res.email;
          fullName = res.fullName;
          msnv = res.msnv;
          userName = res.userName;
          otp = res.otp || null;
        } else if (res && !res.isOffline) {
          showToast(res.message || 'Không tìm thấy tài khoản nhân viên!', 'error');
          return false;
        }
      } catch (err) {
        console.warn('Backend API forgot password failed, fallback to local verify:', err.message);
      }
    }

    // 2. Chế độ dự phòng Offline (tra cứu trực tiếp trong APP_STATE.users)
    if (!email) {
      const uClean = identifier.toLowerCase().trim();
      userObj = (APP_STATE.users || []).find(u =>
        (u.id && u.id.toLowerCase() === uClean) ||
        (u.userName && u.userName.toLowerCase() === uClean) ||
        (u.msnv && u.msnv.toLowerCase() === uClean) ||
        (u.email && u.email.toLowerCase() === uClean) ||
        (u.fullName && u.fullName.toLowerCase() === uClean)
      );

      if (!userObj) {
        showToast(`Không tìm thấy cán bộ nhân viên nào khớp với "${identifier}" trên hệ thống UMC!`, 'error');
        return false;
      }

      email = userObj.email || `${userObj.userName || userObj.msnv || 'user'}@umc.edu.vn`;
      fullName = userObj.fullName;
      msnv = userObj.msnv;
      userName = userObj.userName;
      otp = Math.floor(100000 + Math.random() * 900000).toString();
    }

    // Lưu session khôi phục
    CURRENT_RESET_SESSION = {
      identifier,
      email,
      fullName,
      msnv,
      userName,
      otp,
      user: userObj,
      expiresAt: Date.now() + 15 * 60 * 1000
    };

    // Cập nhật giao diện Bước 2
    const elEmail = document.getElementById('forgot-sent-email');
    const elName = document.getElementById('forgot-sent-name');
    const elMsnv = document.getElementById('forgot-sent-msnv');
    const elEmailDisplay = document.getElementById('forgot-sent-email-display');
    const otpInput = document.getElementById('forgot-otp-input');
    const newPwdInput = document.getElementById('forgot-new-password');
    const confirmPwdInput = document.getElementById('forgot-confirm-password');

    if (elEmail) elEmail.textContent = email;
    if (elName) elName.textContent = fullName;
    if (elMsnv) elMsnv.textContent = msnv || '--';
    if (elEmailDisplay) elEmailDisplay.textContent = email;
    if (otpInput) otpInput.value = '';
    if (newPwdInput) newPwdInput.value = '';
    if (confirmPwdInput) confirmPwdInput.value = '';

    const step1 = document.getElementById('forgot-step-1');
    const step2 = document.getElementById('forgot-step-2');
    if (step1) step1.classList.add('hidden');
    if (step2) step2.classList.remove('hidden');

    showToast(`Đã gửi thông tin và mã xác thực đến email UMC: ${email}`, 'success');
    if (otpInput) otpInput.focus();

    return true;
  } finally {
    if (btn) btn.disabled = false;
    if (btnText) btnText.textContent = '📩 GỬI MÃ XÁC THỰC VỀ EMAIL UMC';
  }
}

async function handleConfirmResetPassword(event) {
  if (event) event.preventDefault();
  if (!CURRENT_RESET_SESSION) {
    showToast('Phiên làm việc không hợp lệ. Vui lòng thử lại từ đầu!', 'warning');
    backToStep1Forgot();
    return false;
  }

  if (Date.now() > CURRENT_RESET_SESSION.expiresAt) {
    showToast('Mã OTP đã hết hiệu lực (sau 15 phút). Vui lòng yêu cầu gửi lại!', 'error');
    return false;
  }

  const otpInput = document.getElementById('forgot-otp-input');
  const newPwdInput = document.getElementById('forgot-new-password');
  const confirmPwdInput = document.getElementById('forgot-confirm-password');
  const btn = document.getElementById('btn-confirm-reset');
  const btnText = document.getElementById('btn-confirm-reset-text');

  const otp = otpInput ? otpInput.value.trim() : '';
  const newPwd = newPwdInput ? newPwdInput.value : '';
  const confirmPwd = confirmPwdInput ? confirmPwdInput.value : '';

  if (!otp) {
    showToast('Vui lòng nhập mã xác thực OTP từ email!', 'warning');
    if (otpInput) otpInput.focus();
    return false;
  }

  if (CURRENT_RESET_SESSION.otp && otp !== CURRENT_RESET_SESSION.otp) {
    showToast('Mã xác thực OTP không chính xác. Vui lòng kiểm tra lại hòm thư UMC!', 'error');
    if (otpInput) otpInput.focus();
    return false;
  }

  if (!newPwd || newPwd.length < 3) {
    showToast('Mật khẩu mới phải có tối thiểu 3 ký tự!', 'warning');
    if (newPwdInput) newPwdInput.focus();
    return false;
  }

  if (newPwd !== confirmPwd) {
    showToast('Mật khẩu xác nhận không trùng khớp!', 'warning');
    if (confirmPwdInput) confirmPwdInput.focus();
    return false;
  }

  if (btn) btn.disabled = true;
  if (btnText) btnText.textContent = 'ĐANG ĐỔI MẬT KHẨU...';

  try {
    // 1. Cập nhật qua Backend API nếu có (Backend sẽ kiểm tra OTP trong resetOtpCache)
    if (typeof apiResetPassword === 'function') {
      try {
        const resetRes = await apiResetPassword(CURRENT_RESET_SESSION.identifier, otp, newPwd);
        if (resetRes && !resetRes.success && !resetRes.isOffline) {
          showToast(resetRes.message || 'Mã xác thực OTP không chính xác hoặc đã hết hạn!', 'error');
          if (btn) btn.disabled = false;
          if (btnText) btnText.textContent = '🔒 XÁC NHẬN & ĐỔI MẬT KHẨU';
          if (otpInput) otpInput.focus();
          return false;
        }
      } catch (err) {
        console.warn('Backend API reset failed, fallback to local update:', err.message);
      }
    }

    // 2. Cập nhật bộ nhớ cục bộ & localStorage
    const uClean = CURRENT_RESET_SESSION.identifier.toLowerCase().trim();
    const user = (APP_STATE.users || []).find(u =>
      (u.id && u.id.toLowerCase() === uClean) ||
      (u.userName && u.userName.toLowerCase() === uClean) ||
      (u.msnv && u.msnv.toLowerCase() === uClean) ||
      (u.email && u.email.toLowerCase() === uClean) ||
      (u.fullName && u.fullName.toLowerCase() === uClean)
    );

    if (user) {
      user.password = newPwd;
    }
    if (CURRENT_RESET_SESSION.user) {
      CURRENT_RESET_SESSION.user.password = newPwd;
    }

    try {
      localStorage.setItem('umc_users_custom', JSON.stringify(APP_STATE.users));
    } catch (e) {}

    // Lưu mật khẩu mới để auto-fill sau khi đóng modal
    CURRENT_RESET_SESSION.newPassword = newPwd;

    // Chuyển sang Bước 3 (Thành công)
    const step2 = document.getElementById('forgot-step-2');
    const step3 = document.getElementById('forgot-step-3');
    if (step2) step2.classList.add('hidden');
    if (step3) step3.classList.remove('hidden');

    if (typeof confetti === 'function') {
      confetti({ particleCount: 80, spread: 70, origin: { y: 0.6 } });
    }

    showToast('Đặt lại mật khẩu thành công!', 'success');
    return true;
  } finally {
    if (btn) btn.disabled = false;
    if (btnText) btnText.textContent = '🔒 XÁC NHẬN ĐỔI MẬT KHẨU MỚI';
  }
}

async function resendResetOtp() {
  if (!CURRENT_RESET_SESSION) {
    backToStep1Forgot();
    return;
  }

  const btnResend = document.getElementById('btn-resend-otp');
  if (btnResend) btnResend.disabled = true;

  try {
    if (typeof apiForgotPassword === 'function') {
      try {
        await apiForgotPassword(CURRENT_RESET_SESSION.identifier);
      } catch (e) {
        console.warn('Gửi lại OTP qua Backend thất bại:', e.message);
      }
    }

    CURRENT_RESET_SESSION.expiresAt = Date.now() + 15 * 60 * 1000;
    
    const otpInput = document.getElementById('forgot-otp-input');
    if (otpInput) {
      otpInput.value = '';
      otpInput.focus();
    }

    showToast(`Đã phát hành mã OTP mới và gửi bí mật đến email công vụ: ${CURRENT_RESET_SESSION.email}. Vui lòng kiểm tra hòm thư!`, 'success');
  } finally {
    if (btnResend) {
      setTimeout(() => {
        btnResend.disabled = false;
      }, 3000);
    }
  }
}

function finishPasswordReset() {
  const modal = document.getElementById('modal-forgot-password');
  if (modal) modal.classList.add('hidden');

  if (CURRENT_RESET_SESSION) {
    const loginUserInput = document.getElementById('login-username');
    const loginPwdInput = document.getElementById('login-password');
    if (loginUserInput) loginUserInput.value = CURRENT_RESET_SESSION.userName || CURRENT_RESET_SESSION.msnv || CURRENT_RESET_SESSION.identifier;
    if (loginPwdInput && CURRENT_RESET_SESSION.newPassword) loginPwdInput.value = CURRENT_RESET_SESSION.newPassword;
    showToast('Đã tự động điền tài khoản và mật khẩu mới. Bạn có thể nhấn Đăng Nhập!', 'info');
  }
}

function updateHeaderUserInfo() {
  const user = APP_STATE.currentUser;
  if (!user) return;
  
  const nameEl = document.getElementById('current-user-name'); if (nameEl) nameEl.textContent = user.fullName;
  const roleEl = document.getElementById('current-user-role-badge'); if (roleEl) roleEl.textContent = user.roleName;
  const deptEl = document.getElementById('current-user-dept'); if (deptEl) deptEl.textContent = user.department;
  const avatarEl = document.getElementById('current-user-avatar'); if (avatarEl) avatarEl.src = user.avatar;
  const roleSelect = document.getElementById('quick-role-select'); if (roleSelect) roleSelect.value = user.id;
}

function _legacyUpdateRoleVisibility() {
  const user = APP_STATE.currentUser;
  if (!user) return;
  const isApprover = ['head_nurse', 'nurse_board', 'director', 'admin'].includes(user.role);
  const batchBtn = document.getElementById('btn-batch-approve-leader');
  if (batchBtn) {
    batchBtn.style.display = ['director', 'admin'].includes(user.role) ? 'inline-flex' : 'none';
  }
}

// Chuyển Tab (Hỗ trợ cả .tab-content và .tab-pane)
function _legacySwitchTab(tabId) {
  // Xác định tab chính tương ứng trên top navigation
  let mainNavId = tabId;
  if (tabId === 'portfolio') {
    mainNavId = 'assessment';
  } else if (['tiers', 'honor', 'analytics', 'idp', 'stats', 'reports'].includes(tabId)) {
    mainNavId = 'reports';
  }
  APP_STATE.activeTab = mainNavId;
  
  // Ẩn tất cả tab content
  document.querySelectorAll('.tab-content, .tab-pane').forEach(el => el.classList.add('hidden'));
  
  // Cập nhật trạng thái active trên 4 tab chính
  document.querySelectorAll('.nav-tab-btn').forEach(btn => {
    btn.classList.remove('bg-white', 'text-[#004b87]', 'shadow-sm');
    btn.classList.add('text-blue-100', 'hover:bg-white/15');
  });
  
  const activeBtn = document.getElementById(`nav-btn-${mainNavId}`);
  if (activeBtn) {
    activeBtn.classList.add('bg-white', 'text-[#004b87]', 'shadow-sm');
    activeBtn.classList.remove('text-blue-100', 'hover:bg-white/15');
  }
  
  // Hiển thị view phù hợp
  if (tabId === 'status') {
    const pane = document.getElementById('tab-status');
    if (pane) pane.classList.remove('hidden');
    if (typeof renderStatusTab === 'function') renderStatusTab();
  } else if (tabId === 'assessment') {
    const activePane = document.getElementById('tab-assessment');
    if (activePane) activePane.classList.remove('hidden');
    renderAssessmentTab();
  } else if (tabId === 'portfolio') {
    const activePane = document.getElementById('tab-portfolio');
    if (activePane) activePane.classList.remove('hidden');
    renderPortfolioTab();
  } else if (tabId === 'approval') {
    const activePane = document.getElementById('tab-approval');
    if (activePane) activePane.classList.remove('hidden');
    renderApprovalsTab();
  } else if (tabId === 'admin') {
    const activePane = document.getElementById('tab-admin');
    if (activePane) activePane.classList.remove('hidden');
    renderAdminTab();
  } else if (mainNavId === 'reports') {
    const activePane = document.getElementById('tab-reports');
    if (activePane) activePane.classList.remove('hidden');
    const targetSub = ['staff', 'criteria', 'tiers', 'honor', 'analytics', 'idp', 'stats'].includes(tabId) ? tabId : (APP_STATE.activeReportSubTab || 'staff');
    switchReportSubTab(targetSub);
  }
}

// Chuyển Sub-Tab trong Trung tâm Báo Cáo & Xếp Bậc
function switchReportSubTab(subTabId) {
  APP_STATE.activeReportSubTab = subTabId;
  
  // Ẩn tất cả subpane
  document.querySelectorAll('.report-subpane').forEach(el => el.classList.add('hidden'));
  
  // Đặt lại style các nút pill
  document.querySelectorAll('.sub-tab-btn').forEach(btn => {
    btn.classList.remove('bg-white', 'text-blue-800', 'shadow-xs');
    btn.classList.add('text-slate-600', 'hover:text-slate-900');
  });
  
  // Kích hoạt subpane được chọn
  const activePane = document.getElementById(`subpane-${subTabId}`);
  if (activePane) activePane.classList.remove('hidden');
  
  const activeBtn = document.getElementById(`sub-nav-${subTabId}`);
  if (activeBtn) {
    activeBtn.classList.add('bg-white', 'text-blue-800', 'shadow-xs');
    activeBtn.classList.remove('text-slate-600', 'hover:text-slate-900');
  }
  
  // Render dữ liệu tương ứng
  if (subTabId === 'tiers') renderTiersTab();
  else if (subTabId === 'honor') renderHonorTab();
  else if (subTabId === 'analytics') renderAnalyticsTab();
  else if (subTabId === 'stats') renderReportsTab();
  else if (subTabId === 'idp') renderIDPTab();
}

// =========================================================================
// 4. QUẢN LÝ HỒ SƠ ĐÁNH GIÁ (SUBMISSION & ASSESSMENT)
// =========================================================================
// =========================================================================
function getUserSubmission(userId, year) {
  const y = parseInt(year) || APP_STATE.selectedEvaluationYear || 2026;
  let sub = APP_STATE.submissions.find(s => s.userId === userId && parseInt(s.year) === y);
  if (!sub) {
    const user = APP_STATE.users.find(u => u.id === userId);
    sub = {
      id: `sub_${y}_${userId}`,
      userId: userId,
      msnv: user ? user.msnv : '',
      fullName: user ? user.fullName : '',
      department: user ? user.department : '',
      specialty: user ? user.specialty : 'lamsang',
      year: y,
      status: 'draft',
      statusLabel: WORKFLOW_STAGES.draft.label,
      currentTier: user ? user.level : 1,
      targetTier: user ? Math.min(7, user.level + 1) : 2,
      evaluatedTier: user ? user.level : 1,
      totalScore: 0,
      domainScores: {},
      scores: {},
      criterionEvidences: {},
      history: [
        { step: 'Tạo hồ sơ', actor: user ? user.fullName : 'Hệ thống', date: new Date().toLocaleString('vi-VN'), comment: `Khởi tạo đợt tự đánh giá năng lực năm ${y}`, action: 'draft' }
      ]
    };
    APP_STATE.submissions.push(sub);
    saveStorage();
  }
  if (!Array.isArray(sub.history)) sub.history = Array.isArray(sub.timeline) ? sub.timeline : [];
  const hasCritEv = sub.criterionEvidences && typeof sub.criterionEvidences === 'object' && Object.keys(sub.criterionEvidences).length > 0;
  const hasLegEv = sub.evidences && typeof sub.evidences === 'object' && Object.keys(sub.evidences).length > 0;
  if (!hasCritEv && hasLegEv) {
    sub.criterionEvidences = { ...sub.evidences };
  } else if (!sub.criterionEvidences || typeof sub.criterionEvidences !== 'object') {
    sub.criterionEvidences = {};
  }
  sub.evidences = sub.criterionEvidences;
  if (!sub.year) sub.year = y;
  return sub;
}

