// Khởi tạo và nạp dữ liệu đánh giá của người dùng
function loadUserSubmission(userId, year) {
  const currentYear = parseInt(year) || APP_STATE.selectedEvaluationYear || 2026;
  const sub = getUserSubmission(userId, currentYear);
  APP_STATE.currentAssessmentScores = sub.scores ? { ...sub.scores } : {};
  APP_STATE.currentCriterionEvidences = (sub.criterionEvidences && Object.keys(sub.criterionEvidences).length > 0)
    ? { ...sub.criterionEvidences }
    : (sub.evidences ? { ...sub.evidences } : {});
  APP_STATE.currentAssessmentOptionKeys = sub.optionKeys ? { ...sub.optionKeys } : {};
  APP_STATE.managerAssessmentScores = sub.managerScores ? { ...sub.managerScores } : {};
  if (sub.specialty) {
    APP_STATE.selectedSpecialty = sub.specialty;
  }
  if (!APP_STATE.assessmentViewMode) {
    APP_STATE.assessmentViewMode = 'grid'; // Mặc định chế độ Bảng Lâm Sàng Hàng Ngang
  }
}

// Render Tab Đánh Giá Năng Lực
function renderAssessmentTab() {
  const user = APP_STATE.currentUser;
  if (!user) return;
  loadUserSubmission(user.id);
  
  const sub = getUserSubmission(user.id);
  const deptSpecialty = getDepartmentSpecialty(user.department);
  const isAdmin = user.role === 'admin' || user.id === 'usr_admin';
  const specialty = isAdmin ? (APP_STATE.selectedSpecialty || deptSpecialty) : deptSpecialty;
  APP_STATE.selectedSpecialty = specialty;
  user.specialty = specialty;
  if (sub) sub.specialty = specialty;
  const allDomains = DOMAINS_BY_SPECIALTY[specialty] || [];
  
  renderProfileHeaderCard(user, sub);
  renderAssessmentGuidelineBanner();
  
  const activeDomain = APP_STATE.activeAssessmentDomain || 'all';
  const viewMode = APP_STATE.assessmentViewMode || 'grid';
  const statusFilter = APP_STATE.assessmentStatusFilter || 'all';
  const searchQuery = (APP_STATE.assessmentSearchQuery || '').trim().toLowerCase();
  
  // Tính tổng tiến độ chấm
  let overallTotal = 0;
  let overallScored = 0;
  allDomains.forEach(d => {
    (d.standards || []).forEach(s => {
      (s.criteria || []).forEach(c => {
        overallTotal++;
        if ((APP_STATE.currentAssessmentScores[c.id] || 0) > 0) overallScored++;
      });
    });
  });
  const overallPct = overallTotal > 0 ? Math.round((overallScored / overallTotal) * 100) : 0;
  
  // Render Toolbar và Tab Lĩnh Vực
  const tabsBar = document.getElementById('assessment-domain-tabs-bar');
  if (tabsBar) {
    tabsBar.innerHTML = `
      <div class="w-full space-y-3">
        
        <!-- 5 Tabs Lĩnh Vực với Điểm Trực Tiếp -->
        <div class="flex items-center gap-2 overflow-x-auto pb-1 text-xs">
          <button type="button" onclick="switchAssessmentDomain('all')" class="domain-tab-btn px-3.5 py-2 rounded-xl font-bold transition-all whitespace-nowrap flex items-center gap-1.5 ${
            activeDomain === 'all' 
              ? 'bg-blue-700 text-white shadow-xs font-black' 
              : 'bg-white text-slate-700 hover:bg-slate-100 border border-slate-200'
          }">
            <span>🌟 Toàn Bộ 5 Lĩnh Vực</span>
            <span class="px-1.5 py-0.2 rounded-full ${activeDomain === 'all' ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-600'} text-[10px] font-black">${overallTotal} TC</span>
          </button>

          ${allDomains.map((d, dIdx) => {
            let dCritCount = 0;
            let dScoredCount = 0;
            (d.standards || []).forEach(s => {
              (s.criteria || []).forEach(c => {
                dCritCount++;
                if ((APP_STATE.currentAssessmentScores[c.id] || 0) > 0) dScoredCount++;
              });
            });
            const isActive = activeDomain === d.id;
            const dScore = sub.domainScores ? (sub.domainScores[d.id] || 0) : 0;
            return `
              <button type="button" onclick="switchAssessmentDomain('${d.id}')" class="domain-tab-btn px-3.5 py-2 rounded-xl font-bold transition-all whitespace-nowrap flex items-center gap-1.5 ${
                isActive 
                  ? 'bg-blue-700 text-white shadow-xs font-black' 
                  : 'bg-white text-slate-700 hover:bg-slate-100 border border-slate-200'
              }">
                <span>${d.code} ${d.name.replace(/^I+\.\s*/, '').substring(0, 24)}</span>
                <span class="px-1.5 py-0.2 rounded-full text-[10px] font-black ${
                  isActive ? 'bg-white/20 text-white' : 'bg-blue-50 text-blue-800 border border-blue-200'
                }">
                  <span id="domain-pill-score-${d.id}">${dScore}</span>/${d.maxPoints || 200}đ
                </span>
                <span class="text-[10px] opacity-80 hidden md:inline">(${dScoredCount}/${dCritCount})</span>
              </button>
            `;
          }).join('')}
        </div>

        <!-- Thanh Tìm Kiếm, Bộ Lọc & Nút Chuyển Đổi Chế Độ Xem -->
        <div class="bg-white p-3 rounded-2xl border border-slate-200 shadow-2xs flex flex-col lg:flex-row lg:items-center justify-between gap-3">
          
          <!-- Trái: Hộp Tìm Kiếm & Bộ Lọc Trạng Thái -->
          <div class="flex items-center gap-2.5 flex-wrap flex-1">
            <div class="relative w-full sm:w-80">
              <input type="text" 
                id="assessment-search-input"
                value="${APP_STATE.assessmentSearchQuery || ''}"
                oninput="onAssessmentSearchInput(this.value)"
                placeholder="🔍 Tìm tiêu chí, kỹ thuật, 5 đúng, CPR, ISBAR..." 
                class="w-full pl-3 pr-7 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:outline-none focus:border-blue-500 focus:bg-white transition-all">
              ${APP_STATE.assessmentSearchQuery ? `
                <button type="button" onclick="clearAssessmentSearch()" class="absolute right-2.5 top-1.5 text-slate-400 hover:text-slate-600 font-bold text-xs">✕</button>
              ` : ''}
            </div>

            <div class="inline-flex items-center bg-slate-100 p-0.5 rounded-xl border border-slate-200 text-xs">
              <button type="button" onclick="setAssessmentStatusFilter('all')" class="px-2.5 py-1 rounded-lg font-bold transition-all ${
                statusFilter === 'all' ? 'bg-white text-blue-800 shadow-2xs' : 'text-slate-600 hover:text-slate-900'
              }">
                Tất cả (${overallTotal})
              </button>
              <button type="button" onclick="setAssessmentStatusFilter('unscored')" class="px-2.5 py-1 rounded-lg font-bold transition-all ${
                statusFilter === 'unscored' ? 'bg-white text-amber-800 shadow-2xs' : 'text-slate-600 hover:text-slate-900'
              }">
                Chưa chấm (${overallTotal - overallScored})
              </button>
              <button type="button" onclick="setAssessmentStatusFilter('scored')" class="px-2.5 py-1 rounded-lg font-bold transition-all ${
                statusFilter === 'scored' ? 'bg-white text-emerald-800 shadow-2xs' : 'text-slate-600 hover:text-slate-900'
              }">
                Đã chấm (${overallScored})
              </button>
            </div>
          </div>

          <!-- Phải: Nút Chuyển Đổi Chế Độ Xem (Bảng Hàng Ngang, Dạng Thẻ, Thu Gọn) -->
          <div class="flex items-center gap-2 self-end lg:self-center">
            <span class="text-xs text-slate-400 font-bold hidden sm:inline">Chế độ xem:</span>
            <div class="inline-flex items-center bg-slate-100 p-0.5 rounded-xl border border-slate-200 text-xs">
              <button type="button" onclick="setAssessmentViewMode('grid')" title="Phiếu đánh giá hàng ngang - Tiêu chí & câu trả lời viết trải rộng hết hàng mới xuống hàng" class="px-3.5 py-1.5 rounded-lg font-bold transition-all flex items-center gap-1.5 ${
                viewMode === 'grid' || viewMode === 'cards' ? 'bg-white text-blue-800 shadow-2xs' : 'text-slate-600 hover:text-slate-900'
              }">
                <span>📋 Phiếu Đánh Giá Hàng Ngang</span>
              </button>
              <button type="button" onclick="setAssessmentViewMode('compact')" title="Thu gọn chấm điểm nhanh" class="px-3.5 py-1.5 rounded-lg font-bold transition-all flex items-center gap-1.5 ${
                viewMode === 'compact' ? 'bg-white text-blue-800 shadow-2xs' : 'text-slate-600 hover:text-slate-900'
              }">
                <span>⚡ Thu Gọn</span>
              </button>
            </div>
          </div>

        </div>

      </div>
    `;
  }
  
  const isLocked = ['submitted_l1', 'submitted_l2', 'submitted_l3', 'approved'].includes(sub.status);
  const stage = (typeof WORKFLOW_STAGES !== 'undefined' && WORKFLOW_STAGES[sub.status]) ? WORKFLOW_STAGES[sub.status] : { label: 'Bản Nháp' };

  // Thống kê số lượng minh chứng hiện có
  const evidenceMap = APP_STATE.currentCriterionEvidences || sub.criterionEvidences || sub.evidences || {};
  let totalEvFiles = 0;
  Object.keys(evidenceMap).forEach(k => {
    if (Array.isArray(evidenceMap[k])) totalEvFiles += evidenceMap[k].length;
  });

  const statusBannerEl = document.getElementById('assessment-status-banner'); if (statusBannerEl) { statusBannerEl.style.display = 'none'; statusBannerEl.innerHTML = ''; }

  const container = document.getElementById('assessment-domains-container');
  if (!container) return;

  if (allDomains.length === 0) {
    container.innerHTML = `<div class="p-8 text-center text-slate-500 bg-white rounded-2xl border border-slate-200">Đang tải danh mục tiêu chí đánh giá...</div>`;
    return;
  }
  const displayDomains = activeDomain === 'all' ? allDomains : allDomains.filter(d => d.id === activeDomain);
  
  // Hiển thị theo chế độ đã chọn
  if (viewMode === 'grid') {
    renderAssessmentClinicalTable(displayDomains, isLocked, user, sub);
  } else {
    renderAssessmentCardsOrCompact(displayDomains, isLocked, viewMode, searchQuery, statusFilter, user, sub);
  }
  
  calculateAndUpdateAssessmentSummary(sub);
  renderAssessmentSubmissionSection(user, sub, allDomains);
}

