  // Xác định chuyên khoa theo đúng Khoa/Đơn vị của nhân viên
  const deptSpecialty = getDepartmentSpecialty(user.department);
  const isAdmin = user.role === 'admin' || user.id === 'usr_admin';
  const specialty = isAdmin ? (APP_STATE.selectedSpecialty || deptSpecialty) : deptSpecialty;
  
  // Cập nhật đồng bộ APP_STATE và submission
  APP_STATE.selectedSpecialty = specialty;
  user.specialty = specialty;
  if (sub) sub.specialty = specialty;

  const meta = SPECIALTY_META[specialty] || { name: 'Điều Dưỡng Lâm Sàng', icon: '🏥', totalCriteria: 66, badgeClass: 'bg-blue-100 text-blue-800' };
  const currentYear = sub.year || APP_STATE.selectedEvaluationYear || 2026;
