function renderAnalyticsTab() {
  const nurseSelect = document.getElementById('analytics-nurse-select');
  const validUsers = (APP_STATE.users || []).filter(u => u.role !== 'admin');
  
  // Điền dropdown nếu chưa có hoặc số lượng không khớp
  if (nurseSelect && (nurseSelect.options.length === 0 || nurseSelect.options.length !== validUsers.length)) {
    const defaultUserId = (APP_STATE.currentUser && APP_STATE.currentUser.role !== 'admin') 
      ? APP_STATE.currentUser.id 
      : (validUsers[0] ? validUsers[0].id : '');
    nurseSelect.innerHTML = validUsers.map(u => `
      <option value="${u.id}" ${u.id === defaultUserId ? 'selected' : ''}>${u.fullName} (${u.msnv || ''} - ${u.roleName || ''})</option>
    `).join('');
  }
  
  // Xác định nhân sự được chọn từ dropdown
  const selectedId = nurseSelect ? nurseSelect.value : (APP_STATE.currentUser ? APP_STATE.currentUser.id : null);
  const user = validUsers.find(u => u.id === selectedId) || APP_STATE.currentUser;
  if (!user) return;
  
  const titleEl = document.getElementById('analytics-nurse-title'); 
  if (titleEl) titleEl.textContent = `${user.fullName} (MSNV: ${user.msnv || '--'})`;

  const badgeEl = document.getElementById('analytics-nurse-badge');
  if (badgeEl) {
    badgeEl.innerHTML = `<span class="px-2.5 py-1 rounded-full bg-blue-100 text-blue-800 text-xs font-bold border border-blue-200">🎖️ Bậc ${user.level || 1} · ${user.department || 'Khoa Chấn thương Chỉnh hình'}</span>`;
  }
  
  const sub = getUserSubmission(user.id);
  const dScores = {
    d1: (sub && sub.domainScores) ? (sub.domainScores.lamsang_d1 || sub.domainScores.d1 || 90) : 90,
    d2: (sub && sub.domainScores) ? (sub.domainScores.lamsang_d2 || sub.domainScores.d2 || 220) : 220,
    d3: (sub && sub.domainScores) ? (sub.domainScores.lamsang_d3 || sub.domainScores.d3 || 25) : 25,
    d4: (sub && sub.domainScores) ? (sub.domainScores.lamsang_d4 || sub.domainScores.d4 || 25) : 25,
    d5: (sub && sub.domainScores) ? (sub.domainScores.lamsang_d5 || sub.domainScores.d5 || 35) : 35
  };

  const canvas = document.getElementById('radarChartCanvas');
  if (canvas && typeof Chart !== 'undefined') {
    if (APP_STATE.radarChart) {
      APP_STATE.radarChart.destroy();
    }
    const ctx = canvas.getContext('2d');
    APP_STATE.radarChart = new Chart(ctx, {
      type: 'radar',
      data: {
        labels: [
          'I. Bằng Cấp & Chứng Chỉ',
          'II. Chăm Sóc Người Bệnh',
          'III. Đào Tạo & NCKH',
          'IV. Quản Lý & Cải Tiến',
          'V. Phát Triển Nghề Nghiệp'
        ],
        datasets: [
          {
            label: `Điểm số thực tế: ${user.fullName}`,
            data: [dScores.d1, dScores.d2, dScores.d3, dScores.d4, dScores.d5],
            backgroundColor: 'rgba(0, 91, 166, 0.25)',
            borderColor: '#005ba6',
            borderWidth: 2.5,
            pointBackgroundColor: '#005ba6',
            pointRadius: 4
          },
          {
            label: 'Ngưỡng Chuẩn Bậc 3 (Competent)',
            data: [100, 240, 10, 10, 40],
            backgroundColor: 'rgba(245, 158, 11, 0.12)',
            borderColor: '#f59e0b',
            borderWidth: 2,
            borderDash: [4, 4],
            pointBackgroundColor: '#f59e0b',
            pointRadius: 3
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          r: {
            beginAtZero: true,
            pointLabels: {
              font: {
                family: "'Be Vietnam Pro', sans-serif",
                size: 11,
                weight: 'bold'
              }
            }
          }
        },
        plugins: {
          legend: {
            labels: {
              font: {
                family: "'Be Vietnam Pro', sans-serif",
                size: 11
              }
            }
          }
        }
      }
    });
  }
  
  // Gợi ý và đánh giá thế mạnh động theo điểm thực tế của nhân sự
  const recContainer = document.getElementById('analytics-strengths-recommendations');
  if (recContainer) {
    const isHighClinical = dScores.d2 >= 200;
    const isHighResearch = dScores.d3 >= 20;
    const isHighMgmt = dScores.d4 >= 20;

    recContainer.innerHTML = `
      <div class="space-y-3 text-xs">
        <div class="p-3 bg-blue-50/70 border border-blue-200 rounded-xl">
          <span class="font-bold text-blue-900 block mb-1">🌟 Thế mạnh chuyên môn của ${user.fullName}:</span>
          <p class="text-slate-600 leading-relaxed">
            ${isHighClinical ? 'Điểm thực hành chăm sóc lâm sàng vững vàng (Lĩnh vực II đạt ' + dScores.d2 + 'đ), tuân thủ chặt chẽ các quy trình kỹ thuật chuyên khoa.' : 'Đang hoàn thiện năng lực thực hành lâm sàng cơ bản tại khoa.'}
            ${isHighResearch ? ' Có năng lực nghiên cứu khoa học và đào tạo (đạt ' + dScores.d3 + 'đ).' : ''}
          </p>
        </div>
        <div class="p-3 bg-amber-50/70 border border-amber-200 rounded-xl">
          <span class="font-bold text-amber-900 block mb-1">🎯 Gợi ý phân công nhiệm vụ phù hợp:</span>
          <ul class="list-disc pl-4 text-slate-600 space-y-1">
            <li>${user.level >= 4 ? 'Tham gia giảng dạy lâm sàng, hướng dẫn điều dưỡng mới (Preceptor).' : 'Phụ trách ca chăm sóc bệnh nhân chuyên khoa theo dõi sát.'}</li>
            <li>${isHighMgmt ? 'Phân công quản lý an toàn người bệnh, giám sát quy trình 5S tại đơn vị.' : 'Tham gia các buổi sinh hoạt khoa học kỹ thuật của Ban Điều Dưỡng.'}</li>
            <li>Phối hợp cùng Bác sĩ điều trị trong các ca can thiệp chuyên sâu.</li>
          </ul>
        </div>
        <div class="p-3 bg-emerald-50/70 border border-emerald-200 rounded-xl">
          <span class="font-bold text-emerald-900 block mb-1">🚀 Định hướng nâng Bậc tiếp theo (Bậc ${Math.min(7, (user.level || 1) + 1)}):</span>
          <p class="text-slate-600 leading-relaxed">
            Cần tích lũy đủ số tiết đào tạo liên tục CME theo quy định, ${dScores.d3 < 20 ? 'đăng ký thực hiện thêm 01 đề tài NCKH / sáng kiến cải tiến' : 'duy trì điểm thi tay nghề định kỳ'} để đủ điều kiện xét nâng hạng.
          </p>
        </div>
      </div>
    `;
  }
}

