function renderHonorTab() {
  const container = document.getElementById('honor-cards-container');
  if (!container) return;
  
  const validUsers = (APP_STATE.users || []).filter(u => u.role !== 'admin');
  const ranked = validUsers.map(u => {
    const sub = getUserSubmission(u.id);
    const score = (sub && sub.totalScore) ? sub.totalScore : 0;
    const tier = (sub && sub.evaluatedTier) ? sub.evaluatedTier : (u.level || 1);
    return {
      user: u,
      score,
      tier,
      sub
    };
  });

  ranked.sort((a, b) => b.score - a.score);
  const topList = ranked.slice(0, 6);

  const rankTitles = [
    { title: 'Hạng Nhất Toàn Viện', icon: '🥇', border: 'border-amber-400 bg-amber-50 text-amber-900' },
    { title: 'Hạng Nhì Toàn Viện', icon: '🥈', border: 'border-slate-300 bg-slate-50 text-slate-800' },
    { title: 'Hạng Ba Toàn Viện', icon: '🥉', border: 'border-amber-600/50 bg-amber-50 text-amber-800' },
    { title: 'Gương Mặt Xuất Sắc', icon: '🎖️', border: 'border-blue-200 bg-blue-50 text-blue-800' },
    { title: 'Nỗ Lực Điển Hình', icon: '🌟', border: 'border-purple-200 bg-purple-50 text-purple-800' },
    { title: 'Cá Nhân Tiêu Biểu', icon: '💫', border: 'border-emerald-200 bg-emerald-50 text-emerald-800' }
  ];

  container.innerHTML = topList.map((item, idx) => {
    const u = item.user;
    const meta = rankTitles[idx] || { title: 'Cá Nhân Tiêu Biểu', icon: '⭐', border: 'border-slate-200 bg-slate-50 text-slate-800' };
    const avatar = u.avatar || 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=150';
    return `
      <div class="bg-white rounded-3xl border border-slate-200 shadow-xs p-6 hover:shadow-lg transition-all flex flex-col items-center text-center relative overflow-hidden">
        <div class="absolute top-3.5 right-4 text-2xl">${meta.icon}</div>
        <img src="${avatar}" alt="Avatar" class="w-20 h-20 rounded-full border-4 border-amber-300 object-cover shadow-md mb-3">
        <h3 class="text-base font-black text-slate-900">${u.fullName}</h3>
        <p class="text-xs text-blue-700 font-bold mt-0.5">${u.roleName || 'Điều dưỡng'}</p>
        <p class="text-[11px] text-slate-400">${u.department || 'UMC CS2'}</p>
        
        <div class="my-4 w-full bg-slate-50 py-2.5 px-3 rounded-2xl border border-slate-100 flex items-center justify-around text-xs">
          <div>
            <span class="text-[10px] text-slate-400 uppercase block font-semibold">Cấp bậc</span>
            <span class="font-bold text-slate-800">Bậc ${item.tier}</span>
          </div>
          <div class="border-l border-slate-200 pl-3">
            <span class="text-[10px] text-slate-400 uppercase block font-semibold">Tổng điểm</span>
            <span class="font-black text-amber-600">${item.score}đ</span>
          </div>
        </div>
        
        <span class="px-3 py-1 rounded-full text-xs font-bold border ${meta.border}">
          ${meta.icon} ${meta.title}
        </span>
      </div>
    `;
  }).join('');
}

