function renderReportsTab() {
  const canvas = document.getElementById('statsChartCanvas');
  if (!canvas || typeof Chart === 'undefined') return;
  
  if (APP_STATE.statsChart) {
    APP_STATE.statsChart.destroy();
  }

  // TÍNH TOÁN SỐ LIỆU THỰC TẾ TỪ CƠ SỞ DỮ LIỆU NHÂN SỰ
  const validUsers = (APP_STATE.users || []).filter(u => u.role !== 'admin');
  const clinicalTierCounts = [0, 0, 0, 0, 0, 0, 0]; // 7 bậc Khối Lâm Sàng
  const subclinicalTierCounts = [0, 0, 0, 0, 0, 0, 0]; // 7 bậc Khối Cận LS & Khám bệnh

  validUsers.forEach(u => {
    const sub = getUserSubmission(u.id);
    const tier = (sub && sub.evaluatedTier) ? sub.evaluatedTier : (u.level || 1);
    const idx = Math.min(6, Math.max(0, tier - 1));
    if (u.specialty === 'lamsang') {
      clinicalTierCounts[idx]++;
    } else {
      subclinicalTierCounts[idx]++;
    }
  });
  
  const totalClin = clinicalTierCounts.reduce((a, b) => a + b, 0);
  const totalSubclin = subclinicalTierCounts.reduce((a, b) => a + b, 0);
  
  const ctx = canvas.getContext('2d');
  APP_STATE.statsChart = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: ['Bậc 1 (Tập sự)', 'Bậc 2 (Thực hành)', 'Bậc 3 (Đủ năng lực)', 'Bậc 4 (Thành thạo)', 'Bậc 5 (Chuyên gia LS)', 'Bậc 6 (Chuyên gia QL)', 'Bậc 7 (Cao cấp)'],
      datasets: [
        {
          label: `Khối Lâm Sàng (${totalClin} nhân sự)`,
          data: clinicalTierCounts,
          backgroundColor: '#005ba6',
          borderRadius: 6
        },
        {
          label: `Khối Cận Lâm Sàng & Khám Bệnh (${totalSubclin} nhân sự)`,
          data: subclinicalTierCounts,
          backgroundColor: '#00a0e9',
          borderRadius: 6
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          beginAtZero: true,
          ticks: { stepSize: 1 },
          title: { display: true, text: 'Số lượng nhân sự thực tế (Người)' }
        }
      },
      plugins: {
        legend: { position: 'top' },
        tooltip: {
          callbacks: {
            label: function(context) {
              return `${context.dataset.label}: ${context.raw} nhân sự`;
            }
          }
        }
      }
    }
  });
}

