// 7. CÁC MODAL HỆ THỐNG: XÁC NHẬN, CHỨNG NHẬN, SỬA PROFILE
// =========================================================================
function openConfirmModal(config) {
  const modal = document.getElementById('modal-confirm-action');
  if (!modal) return;
  
  const titleEl = document.getElementById('confirm-modal-title'); if (titleEl) titleEl.textContent = config.title || 'Xác nhận thao tác';
  const descEl = document.getElementById('confirm-modal-desc'); if (descEl) descEl.innerHTML = config.message || 'Bạn có chắc chắn muốn thực hiện hành động này?';
  const iconEl = document.getElementById('confirm-modal-icon'); if (iconEl) iconEl.textContent = config.icon || '❓';
  
  const okBtn = document.getElementById('btn-confirm-proceed');
  if (okBtn) {
    okBtn.className = `px-5 py-2.5 rounded-xl text-white font-semibold text-xs transition-all shadow-xs ${config.btnClass || 'bg-blue-700 hover:bg-blue-800'}`;
    okBtn.textContent = config.btnText || 'Xác Nhận';
  }
  
  APP_STATE.pendingConfirmAction = config.onConfirm;
  modal.classList.remove('hidden');
}

function closeConfirmModal() {
  const modal = document.getElementById('modal-confirm-action');
  if (modal) modal.classList.add('hidden');
  APP_STATE.pendingConfirmAction = null;
}

function executeConfirmedAction() {
  try {
    if (typeof APP_STATE.pendingConfirmAction === 'function') {
      APP_STATE.pendingConfirmAction();
    }
  } catch (err) {
    console.error('Lỗi khi thực thi hành động xác nhận:', err);
    showToast('Có lỗi xảy ra: ' + (err.message || err), 'error');
  } finally {
    closeConfirmModal();
  }
}

// Modal Hồ Sơ Cá Nhân
function openEditProfileModal() {
  const user = APP_STATE.currentUser;
  if (!user) return;
  
  const nameInput = document.getElementById('prof-input-name'); if (nameInput) nameInput.value = user.fullName;
  const msnvInput = document.getElementById('prof-input-msnv'); if (msnvInput) msnvInput.value = user.msnv;
  const titleInput = document.getElementById('prof-input-title'); if (titleInput) titleInput.value = user.degree || '';
  const deptInput = document.getElementById('prof-input-dept'); if (deptInput) deptInput.value = user.department;
  const expInput = document.getElementById('prof-input-exp'); if (expInput) expInput.value = user.experienceYears || 5;
  const emailInput = document.getElementById('prof-input-email'); if (emailInput) emailInput.value = user.email || '';
  const phoneInput = document.getElementById('prof-input-phone'); if (phoneInput) phoneInput.value = user.phone || '';
  const avatarPreview = document.getElementById('prof-modal-avatar-preview'); if (avatarPreview) avatarPreview.src = user.avatar;
  
  const modal = document.getElementById('modal-edit-profile');
  if (modal) modal.classList.remove('hidden');
}

function closeEditProfileModal() {
  const modal = document.getElementById('modal-edit-profile');
  if (modal) modal.classList.add('hidden');
}

function saveUserProfile(event) {
  if (event) event.preventDefault();
  const user = APP_STATE.currentUser;
  if (!user) return;
  
  const nameInput = document.getElementById('prof-input-name'); if (nameInput) user.fullName = nameInput.value.trim();
  const titleInput = document.getElementById('prof-input-title'); if (titleInput) user.degree = titleInput.value.trim();
  const deptInput = document.getElementById('prof-input-dept'); if (deptInput) user.department = deptInput.value.trim();
  const expInput = document.getElementById('prof-input-exp'); if (expInput) user.experienceYears = parseFloat(expInput.value) || user.experienceYears;
  const emailInput = document.getElementById('prof-input-email'); if (emailInput) user.email = emailInput.value.trim();
  const phoneInput = document.getElementById('prof-input-phone'); if (phoneInput) user.phone = phoneInput.value.trim();
  
  const avatarPreview = document.getElementById('prof-modal-avatar-preview');
  if (avatarPreview && avatarPreview.src) user.avatar = avatarPreview.src;
  
  saveStorage();
  updateHeaderUserInfo();
  closeEditProfileModal();
  showToast('Đã cập nhật thông tin hồ sơ nhân sự thành công!', 'success');
}

