// QUẢN LÝ ẢNH ĐẠI DIỆN HỒ SƠ NHÂN SỰ (AVATAR SUBSYSTEM - NÉN CANVAS & ĐỒNG BỘ)
// =========================================================================

// Danh sách ảnh mẫu nhân viên y tế chuẩn UMC
const UMC_PRESET_AVATARS = [
  { label: 'Điều dưỡng Nữ 1', url: 'https://images.unsplash.com/photo-1594824813627-2c13702a4bf7?w=150' },
  { label: 'Điều dưỡng Nữ 2', url: 'https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=150' },
  { label: 'Điều dưỡng Nữ 3', url: 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=150' },
  { label: 'Điều dưỡng Nữ 4', url: 'https://images.unsplash.com/photo-1582750433449-648ed127bb54?w=150' },
  { label: 'Điều dưỡng/KTV Nam 1', url: 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=150' },
  { label: 'Điều dưỡng/KTV Nam 2', url: 'https://images.unsplash.com/photo-1537368910025-700350fe46c7?w=150' }
];

let _activeAvatarSource = 'global';

/**
 * Nén và thay đổi kích thước ảnh bằng HTML5 Canvas
 * Tránh lỗi QuotaExceededError (5MB) khi lưu base64 vào localStorage
 */
function compressAndResizeImage(file, maxWidth = 280, maxHeight = 280, quality = 0.88) {
  return new Promise((resolve, reject) => {
    if (!file || !file.type.startsWith('image/')) {
      return reject(new Error('Tệp đã chọn không phải là hình ảnh hợp lệ (JPG, PNG, WEBP).'));
    }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Không thể đọc tệp hình ảnh đã chọn.'));
    reader.onload = (e) => {
      const img = new Image();
      img.onerror = () => reject(new Error('Hình ảnh bị lỗi hoặc không hỗ trợ giải mã.'));
      img.onload = () => {
        let width = img.width;
        let height = img.height;

        if (width > height) {
          if (width > maxWidth) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          }
        } else {
          if (height > maxHeight) {
            width = Math.round((width * maxHeight) / height);
            height = maxHeight;
          }
        }

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(img, 0, 0, width, height);

        const dataUrl = canvas.toDataURL('image/jpeg', quality);
        resolve(dataUrl);
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

/**
 * Kích hoạt hộp thoại chọn file ảnh máy tính
 */
function triggerAvatarUpload(source = 'global') {
  _activeAvatarSource = source;
  const input = document.getElementById('global-user-avatar-input') || document.getElementById('prof-input-avatar-file');
  if (input) {
    input.value = '';
    input.click();
  }
}

/**
 * Xử lý khi người dùng chọn file ảnh đại diện từ máy tính
 */
async function handleGlobalAvatarUpload(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;

  if (!file.type.startsWith('image/')) {
    showToast('Vui lòng chọn một tệp hình ảnh hợp lệ (PNG, JPG, WEBP)!', 'warning');
    return;
  }

  if (file.size > 10 * 1024 * 1024) {
    showToast('Tệp ảnh quá lớn (>10MB). Vui lòng chọn tệp nhỏ hơn!', 'warning');
    return;
  }

  try {
    const compressedDataUrl = await compressAndResizeImage(file, 280, 280, 0.88);
    applyNewAvatarUrl(compressedDataUrl);
    showToast('Cập nhật ảnh đại diện hồ sơ cá nhân thành công! 🎉', 'success');
  } catch (err) {
    console.error('Lỗi nén ảnh avatar:', err);
    showToast('Không thể xử lý hình ảnh: ' + (err.message || 'Lỗi không xác định'), 'error');
  }
}

/**
 * Gán URL ảnh đại diện mới vào user, lưu LocalStorage và cập nhật DOM
 */
function applyNewAvatarUrl(avatarUrl) {
  const user = APP_STATE.currentUser;
  if (!user || !avatarUrl) return;

  user.avatar = avatarUrl;

  const targetUser = (APP_STATE.users || []).find(u => u.id === user.id);
  if (targetUser) targetUser.avatar = avatarUrl;

  const sub = getUserSubmission(user.id);
  if (sub) sub.avatar = avatarUrl;

  saveStorage();
  updateAllAvatarDisplays(avatarUrl);
}

/**
 * Cập nhật đồng bộ ảnh đại diện trên toàn bộ các vị trí giao diện
 */
function updateAllAvatarDisplays(avatarUrl) {
  if (!avatarUrl) return;

  // 1. Header avatar
  const headerAvatar = document.getElementById('current-user-avatar');
  if (headerAvatar) headerAvatar.src = avatarUrl;

  // 2. Assessment card avatar
  const assessAvatar = document.getElementById('assessment-user-avatar-img');
  if (assessAvatar) assessAvatar.src = avatarUrl;

  // 3. Portfolio hero avatar
  const portfolioAvatar = document.getElementById('portfolio-owner-avatar');
  if (portfolioAvatar && (!APP_STATE.portfolioSelectedUserId || APP_STATE.portfolioSelectedUserId === APP_STATE.currentUser?.id)) {
    portfolioAvatar.src = avatarUrl;
  }

  // 4. Modal 14 trường thông tin preview
  const modal14Preview = document.getElementById('modal-14-avatar-preview');
  if (modal14Preview) modal14Preview.src = avatarUrl;

  // 5. Modal edit profile preview
  const modalEditPreview = document.getElementById('prof-modal-avatar-preview');
  if (modalEditPreview) modalEditPreview.src = avatarUrl;
  const modalEditData = document.getElementById('prof-input-avatar-data');
  if (modalEditData) modalEditData.value = avatarUrl;
}

/**
 * Đặt lại ảnh đại diện mặc định theo giới tính
 */
function resetAvatarToDefault() {
  const user = APP_STATE.currentUser;
  if (!user) return;
  const isMale = user.gender === 'Nam';
  const defaultAvatar = isMale
    ? 'https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=150'
    : 'https://images.unsplash.com/photo-1594824813627-2c13702a4bf7?w=150';

  applyNewAvatarUrl(defaultAvatar);
  showToast('Đã đặt lại ảnh đại diện mặc định!', 'info');
}

