function viewCertificate(userId) {
  const user = (userId ? APP_STATE.users.find(u => u.id === userId) : null) || APP_STATE.currentUser;
  if (!user) return;
  const currentYear = APP_STATE.selectedEvaluationYear || 2026;
  const sub = getUserSubmission(user.id, currentYear) || {};
  const tierObj = COMPETENCY_TIERS_MATRIX.find(t => t.tier === (sub.evaluatedTier || sub.approvedTier || user.level)) || COMPETENCY_TIERS_MATRIX[0];
  
  const nameEl = document.getElementById('cert-user-name'); if (nameEl) nameEl.textContent = (user.fullName || '').toUpperCase();
  const msnvEl = document.getElementById('cert-user-msnv'); if (msnvEl) msnvEl.textContent = user.msnv || 'UMC-0000';
  const deptEl = document.getElementById('cert-user-dept'); if (deptEl) deptEl.textContent = user.department || 'Bệnh viện Đại học Y Dược TP.HCM';
  const titleEl = document.getElementById('cert-level-title'); if (titleEl) titleEl.textContent = `${tierObj.name}: ${tierObj.title}`;
  const scoreEl = document.getElementById('cert-score'); if (scoreEl) scoreEl.textContent = `${sub.totalScore || 0} / 1000`;
  const dateEl = document.getElementById('cert-date'); if (dateEl) {
    dateEl.textContent = sub.approvedAt ? new Date(sub.approvedAt).toLocaleDateString('vi-VN') : new Date().toLocaleDateString('vi-VN');
  }
  
  const modal = document.getElementById('modal-certificate');
  if (modal) modal.classList.remove('hidden');
}

