function openCreateAssessmentModal() {
  const modal = document.getElementById('modal-create-assessment');
  if (!modal) return;

  const user = APP_STATE.currentUser || (APP_STATE.users && APP_STATE.users[0]);
  const currentYear = APP_STATE.selectedEvaluationYear || APP_STATE.currentEvaluationYear || (new Date().getFullYear());

  const nameInput = document.getElementById('create-input-name');
  if (nameInput) nameInput.value = (user && user.fullName) || '';

  const msnvInput = document.getElementById('create-input-msnv');
  if (msnvInput) msnvInput.value = (user && user.msnv) || '';

  const yearInput = document.getElementById('create-input-year');
  if (yearInput) yearInput.value = currentYear;

  const titleInput = document.getElementById('create-input-title');
  if (titleInput) titleInput.value = (user && user.title) || 'Cử nhân Điều dưỡng';

  const expInput = document.getElementById('create-input-exp');
  if (expInput) expInput.value = (user && user.experienceYears) || 5;

  const phoneInput = document.getElementById('create-input-phone');
  if (phoneInput) phoneInput.value = (user && user.phone) || '';

  const emailInput = document.getElementById('create-input-email');
  if (emailInput) emailInput.value = (user && user.email) || '';

  const avatarUrl = (user && user.avatar) || 'https://images.unsplash.com/photo-1594824813627-2c13702a4bf7?w=150';
  const previewImg = document.getElementById('create-modal-avatar-preview');
  if (previewImg) previewImg.src = avatarUrl;
  const avatarData = document.getElementById('create-input-avatar-data');
  if (avatarData) avatarData.value = avatarUrl;

  let specialty = APP_STATE.selectedSpecialty || (user && user.specialty) || 'lamsang';
  if (user && user.department && typeof DEPARTMENT_CONFIG !== 'undefined') {
    const deptMatch = DEPARTMENT_CONFIG.find(d => d.dept === user.department);
    if (deptMatch && deptMatch.specialty) {
      specialty = deptMatch.specialty;
    }
  }

  const radios = document.querySelectorAll('input[name="create_specialty"]');
  radios.forEach(r => {
    r.checked = (r.value === specialty);
  });

  populateCreationDeptSelect(specialty, user ? user.department : null);

  modal.classList.remove('hidden');
}

function closeCreateAssessmentModal() {
  const modal = document.getElementById('modal-create-assessment');
  if (modal) modal.classList.add('hidden');
}

function populateCreationDeptSelect(specialty, selectedDept) {
  const deptSelect = document.getElementById('create-input-dept');
  if (!deptSelect || typeof DEPARTMENT_CONFIG === 'undefined') return;

  const filteredDepts = DEPARTMENT_CONFIG.filter(d => d.specialty === specialty);
  const otherDepts = DEPARTMENT_CONFIG.filter(d => d.specialty !== specialty);

  let html = '';
  if (filteredDepts.length > 0) {
    html += '<optgroup label="Khoa / Phòng thuộc khối chuyên môn đã chọn">';
    filteredDepts.forEach(d => {
      const isSel = (d.dept === selectedDept) ? 'selected' : '';
      html += `<option value="${d.dept}" ${isSel}>${d.dept} (${d.specialtyLabel})</option>`;
    });
    html += '</optgroup>';
  }

  if (otherDepts.length > 0) {
    html += '<optgroup label="Các khoa / phòng khác">';
    otherDepts.forEach(d => {
      const isSel = (d.dept === selectedDept) ? 'selected' : '';
      html += `<option value="${d.dept}" ${isSel}>${d.dept} (${d.specialtyLabel || d.group})</option>`;
    });
    html += '</optgroup>';
  }

  html += `<option value="__other__" ${selectedDept === '__other__' ? 'selected' : ''}>-- Khoa / Đơn vị khác (Nhập thủ công) --</option>`;
  deptSelect.innerHTML = html;

  const customInput = document.getElementById('create-input-dept-custom');
  if (customInput) {
    if (deptSelect.value === '__other__') {
      customInput.classList.remove('hidden');
    } else {
      customInput.classList.add('hidden');
    }
  }
}

function onCreationSpecialtyChanged(val) {
  populateCreationDeptSelect(val);
}

function onCreationDeptSelectChanged(val) {
  const customInput = document.getElementById('create-input-dept-custom');
  if (customInput) {
    if (val === '__other__') {
      customInput.classList.remove('hidden');
      customInput.focus();
    } else {
      customInput.classList.add('hidden');
    }
  }
}

