async function handleCreateNewAssessment(event) {
  if (event) event.preventDefault();

  const user = APP_STATE.currentUser;
  if (!user) {
    showToast('Vui lòng đăng nhập để thực hiện!', 'error');
    return;
  }

  const yearInput = document.getElementById('create-input-year');
  const year = yearInput ? (parseInt(yearInput.value) || 2026) : 2026;

  let specialty = 'lamsang';
  const checkedRadio = document.querySelector('input[name="create_specialty"]:checked');
  if (checkedRadio) specialty = checkedRadio.value;

  const deptSelect = document.getElementById('create-input-dept');
  let department = deptSelect ? deptSelect.value : user.department;
  if (department === '__other__') {
    const customDept = document.getElementById('create-input-dept-custom');
    department = (customDept && customDept.value.trim()) || user.department;
  }

  const nameInput = document.getElementById('create-input-name');
  if (nameInput && nameInput.value.trim()) user.fullName = nameInput.value.trim();

  const msnvInput = document.getElementById('create-input-msnv');
  if (msnvInput && msnvInput.value.trim()) user.msnv = msnvInput.value.trim();

  const titleInput = document.getElementById('create-input-title');
  if (titleInput && titleInput.value.trim()) user.title = titleInput.value.trim();

  const expInput = document.getElementById('create-input-exp');
  if (expInput) user.experienceYears = parseInt(expInput.value) || user.experienceYears || 0;

  const phoneInput = document.getElementById('create-input-phone');
  if (phoneInput) user.phone = phoneInput.value.trim();

  const emailInput = document.getElementById('create-input-email');
  if (emailInput) user.email = emailInput.value.trim();

  const avatarData = document.getElementById('create-input-avatar-data');
  if (avatarData && avatarData.value) user.avatar = avatarData.value;

  user.department = department;
  user.specialty = specialty;
  APP_STATE.selectedSpecialty = specialty;

  let sub = APP_STATE.submissions.find(s => s.userId === user.id && (parseInt(s.year || s.evaluationYear) === year));

  if (!sub) {
    sub = {
      id: `SUB-${user.id}-${year}`,
      userId: user.id,
      fullName: user.fullName,
      msnv: user.msnv,
      department: department,
      specialty: specialty,
      year: year,
      evaluationYear: year,
      status: 'draft',
      statusLabel: 'Bản Nháp (Chưa nộp)',
      totalScore: 0,
      scores: {},
      criterionEvidences: {},
      evidences: {},
      history: [
        {
          step: `Khởi tạo đợt tự đánh giá năm ${year}`,
          actor: `${user.fullName} (${user.roleName || 'Điều dưỡng viên'})`,
          date: new Date().toLocaleString('vi-VN'),
          comment: `Bắt đầu đợt tự đánh giá năng lực mới năm ${year} theo khối ${specialty}`,
          action: 'create'
        }
      ],
      timeline: [
        {
          step: `Khởi tạo đợt tự đánh giá năm ${year}`,
          actor: `${user.fullName} (${user.roleName || 'Điều dưỡng viên'})`,
          date: new Date().toLocaleString('vi-VN'),
          comment: `Bắt đầu đợt tự đánh giá năng lực mới năm ${year} theo khối ${specialty}`,
          action: 'create'
        }
      ],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    APP_STATE.submissions.push(sub);
  } else {
    sub.department = department;
    sub.specialty = specialty;
    sub.year = year;
    sub.evaluationYear = year;
    sub.fullName = user.fullName;
    sub.msnv = user.msnv;
    if (!Array.isArray(sub.history)) sub.history = [];
    if (!Array.isArray(sub.timeline)) sub.timeline = [];
    const hist = {
      step: `Cập nhật đợt đánh giá năm ${year}`,
      actor: `${user.fullName}`,
      date: new Date().toLocaleString('vi-VN'),
      comment: 'Cập nhật lại thông tin khoa phòng và chuyên môn',
      action: 'update'
    };
    sub.history.push(hist);
    sub.timeline.push(hist);
  }

  APP_STATE.selectedEvaluationYear = year;
  APP_STATE.currentEvaluationYear = year;
  user.evaluationYear = year;
  loadUserSubmission(user.id);
  saveStorage();

  if (typeof cloudSyncSubmission === 'function') {
    cloudSyncSubmission(sub).catch(e => console.warn('Cloud sync error on create:', e));
  }
  if (typeof fetch === 'function') {
    fetch(`${getBackendApiUrl()}/submissions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...getAuthHeader() },
      body: JSON.stringify(sub)
    }).catch(e => console.warn('Backend sync error on create:', e));
  }

  closeCreateAssessmentModal();
  renderAllViews();
  showToast(`Đã khởi tạo thành công đợt đánh giá năng lực năm ${year}!`, 'success');
}

