// Lấy hồ sơ chi tiết của người dùng (tự động thích ứng theo thông tin nhân sự)
function getUserDetailedPortfolio(userId) {
  if (!APP_STATE.userDetailedPortfolios) {
    try {
      APP_STATE.userDetailedPortfolios = JSON.parse(localStorage.getItem('umc_user_detailed_portfolios') || '{}');
    } catch(e) {
      APP_STATE.userDetailedPortfolios = {};
    }
  }

  const user = (APP_STATE.users || []).find(u => u.id === userId) || APP_STATE.currentUser || {};
  const customData = APP_STATE.userDetailedPortfolios[userId];
  const staticData = DEFAULT_PORTFOLIO_DATA[userId];

  const defaultCCHN = (user.msnv ? `${String(user.msnv).replace(/[^0-9]/g, '').padStart(6, '0')}/HCM-CCHN` : '002145/HCM-CCHN');
  const defaultScope = `Khám bệnh, chữa bệnh chuyên khoa ${user.department || 'Điều dưỡng'} - Bệnh viện Đại học Y Dược TP.HCM`;
  const defaultJoinYear = user.graduationYear ? user.graduationYear + 1 : (2026 - (user.experienceYears || 5));
  const defaultJoinDate = `01/10/${defaultJoinYear > 2000 ? defaultJoinYear : 2015}`;

  const defaultStrengths = [
    `Năng lực chuyên môn vững vàng trong thực hành chăm sóc và hỗ trợ chuyên môn tại ${user.department || 'Khoa công tác'}.`,
    `Tuân thủ nghiêm ngặt các quy trình kỹ thuật, kiểm soát nhiễm khuẩn và an toàn người bệnh theo chuẩn UMC.`,
    `Tác phong giao tiếp chuẩn mực, giải thích chu đáo và tận tâm phục vụ người bệnh và thân nhân.`,
    `Chủ động, có tinh thần trách nhiệm cao, luôn sẵn sàng hỗ trợ đồng nghiệp trong ca trực và hoạt động của Khoa.`
  ];

  const defaultWeaknesses = [
    `Cần tiếp tục trau dồi nâng cao trình độ ngoại ngữ chuyên ngành y tế để cập nhật tài liệu quốc tế.`,
    `Nâng cao kỹ năng phân tích số liệu và đẩy mạnh tham gia các đề tài nghiên cứu khoa học cấp cơ sở.`,
    `Tiếp tục rèn luyện kỹ năng quản lý thời gian và ứng dụng công nghệ số trong công tác điều dưỡng.`
  ];

  const defaultShortGoals = [
    `Hoàn thành tối thiểu 48 tiết đào tạo liên tục (CME) trong năm ${APP_STATE.selectedEvaluationYear || 2026} theo quy định.`,
    `Hoàn thiện hồ sơ minh chứng năng lực để đề xuất công nhận thăng hạng bậc năng lực tiếp theo.`,
    `Tham gia tích cực vào ít nhất 01 sáng kiến cải tiến hoặc nghiên cứu khoa học của khoa phòng.`,
    `Hoàn thành xuất sắc các chỉ tiêu công tác chuyên môn được giao tại ${user.department || 'Khoa'}.`
  ];

  const defaultLongGoals = [
    `Tiếp tục học tập nâng cao trình độ chuyên môn (Sau đại học / Chuyên khoa sâu).`,
    `Phấn đấu trở thành Chuyên gia Lâm sàng hoặc Cán bộ quản lý Điều dưỡng chủ chốt của Bệnh viện UMC.`,
    `Chủ nhiệm đề tài nghiên cứu khoa học cấp cơ sở và có bài báo cáo tại Hội nghị khoa học Điều dưỡng.`,
    `Tham gia công tác giảng dạy, hướng dẫn thực hành lâm sàng cho thế hệ điều dưỡng trẻ.`
  ];

  const defaultConferences = [
    { year: '2026', time: '03/2026', title: 'Hội nghị Khoa học Điều dưỡng Bệnh viện Đại học Y Dược TP.HCM Lần thứ XV', role: 'Đại biểu tham dự', org: 'Bệnh viện ĐHYD TP.HCM', location: 'TP. Hồ Chí Minh' },
    { year: '2025', time: '11/2025', title: `Hội nghị Chuyên đề Chăm sóc Người bệnh Khoa ${user.department || 'Lâm sàng'}`, role: 'Học viên hoàn thành', org: 'Bệnh viện ĐHYD TP.HCM', location: 'BV ĐHYD TP.HCM' },
    { year: '2025', time: '06/2025', title: 'Lớp tập huấn: Cập nhật An toàn người bệnh và Kiểm soát nhiễm khuẩn bệnh viện', role: 'Học viên (CME 24 tiết)', org: 'Trung tâm Đào tạo Nhân lực Y tế UMC', location: 'TP.HCM' },
    { year: '2024', time: '09/2024', title: 'Hội thảo: Ứng dụng công nghệ thông tin trong quản lý hồ sơ bệnh án điều dưỡng', role: 'Đại biểu tham dự', org: 'Phòng QLCL & Ban Điều Dưỡng UMC', location: 'TP.HCM' }
  ];

  const defaultSocial = [
    { year: '2025', title: `Chương trình Khám bệnh, Tư vấn sức khỏe tình nguyện do Bệnh viện ĐHYD TP.HCM tổ chức`, role: 'Điều dưỡng tình nguyện viên', org: 'Công đoàn & Đoàn Thanh niên UMC', details: 'Tham gia khám và tư vấn sức khỏe miễn phí cho người dân có hoàn cảnh khó khăn.' },
    { year: '2025', title: 'Ngày hội Hiến máu tình nguyện "Giọt Hồng Blouse Trắng UMC"', role: 'Người hiến máu tình nguyện', org: 'Hội Chữ Thập Đỏ BV ĐHYD TP.HCM', details: 'Hiến máu toàn phần hỗ trợ người bệnh cấp cứu.' }
  ];

  const baseData = staticData || {};

  return {
    cchn: (customData && customData.cchn) || baseData.cchn || defaultCCHN,
    cchnScope: (customData && customData.cchnScope) || baseData.cchnScope || defaultScope,
    joinDate: (customData && customData.joinDate) || baseData.joinDate || defaultJoinDate,
    contractType: (customData && customData.contractType) || baseData.contractType || 'Hợp đồng không xác định thời hạn (Biên chế)',
    strengths: (customData && customData.strengths) || baseData.strengths || defaultStrengths,
    weaknesses: (customData && customData.weaknesses) || baseData.weaknesses || defaultWeaknesses,
    shortTermGoals: (customData && customData.shortTermGoals) || baseData.shortTermGoals || defaultShortGoals,
    longTermGoals: (customData && customData.longTermGoals) || baseData.longTermGoals || defaultLongGoals,
    conferences: (customData && customData.conferences) || baseData.conferences || defaultConferences,
    socialActivities: (customData && customData.socialActivities) || baseData.socialActivities || defaultSocial
  };
}

// Lưu hồ sơ chi tiết vào localStorage
function saveUserDetailedPortfolio(userId, data) {
  if (!APP_STATE.userDetailedPortfolios) APP_STATE.userDetailedPortfolios = {};
  APP_STATE.userDetailedPortfolios[userId] = data;
  try {
    localStorage.setItem('umc_user_detailed_portfolios', JSON.stringify(APP_STATE.userDetailedPortfolios));
  } catch(e) {
    console.error('Lỗi khi lưu detailed portfolio:', e);
  }
}

// Mở Modal Chỉnh sửa Điểm mạnh / Điểm yếu / Mục tiêu IDP
function openEditPortfolioIDPModal() {
  const currentUser = APP_STATE.currentUser;
  if (!currentUser) return;
  const data = getUserDetailedPortfolio(currentUser.id);

  // Điền dữ liệu vào form
  const cchnInp = document.getElementById('idp-input-cchn');
  if (cchnInp) cchnInp.value = data.cchn;
  const scopeInp = document.getElementById('idp-input-cchn-scope');
  if (scopeInp) scopeInp.value = data.cchnScope;
  const joinInp = document.getElementById('idp-input-join-date');
  if (joinInp) joinInp.value = data.joinDate;
  
  const strengthsArea = document.getElementById('idp-input-strengths');
  if (strengthsArea) strengthsArea.value = (data.strengths || []).join('\n');

  const weaknessesArea = document.getElementById('idp-input-weaknesses');
  if (weaknessesArea) weaknessesArea.value = (data.weaknesses || []).join('\n');

  const shortTermArea = document.getElementById('idp-input-short-term');
  if (shortTermArea) shortTermArea.value = (data.shortTermGoals || []).join('\n');

  const longTermArea = document.getElementById('idp-input-long-term');
  if (longTermArea) longTermArea.value = (data.longTermGoals || []).join('\n');

  const modal = document.getElementById('modal-edit-portfolio-idp');
  if (modal) modal.classList.remove('hidden');
}

// Đóng Modal IDP
function closeEditPortfolioIDPModal() {
  const modal = document.getElementById('modal-edit-portfolio-idp');
  if (modal) modal.classList.add('hidden');
}

// Lưu IDP Form
function savePortfolioIDP(event) {
  if (event) event.preventDefault();
  const currentUser = APP_STATE.currentUser;
  if (!currentUser) return;

  const currentData = getUserDetailedPortfolio(currentUser.id);

  const parseLines = (val) => (val || '').split('\n').map(s => s.trim()).filter(s => s.length > 0);

  const updatedData = {
    ...currentData,
    cchn: document.getElementById('idp-input-cchn')?.value || currentData.cchn,
    cchnScope: document.getElementById('idp-input-cchn-scope')?.value || currentData.cchnScope,
    joinDate: document.getElementById('idp-input-join-date')?.value || currentData.joinDate,
    strengths: parseLines(document.getElementById('idp-input-strengths')?.value),
    weaknesses: parseLines(document.getElementById('idp-input-weaknesses')?.value),
    shortTermGoals: parseLines(document.getElementById('idp-input-short-term')?.value),
    longTermGoals: parseLines(document.getElementById('idp-input-long-term')?.value)
  };

  saveUserDetailedPortfolio(currentUser.id, updatedData);
  closeEditPortfolioIDPModal();
  renderPortfolioTab(currentUser.id);
  if (typeof confetti === 'function') confetti({ particleCount: 50, spread: 60 });
  showToast('🎉 Đã cập nhật thành công Kế hoạch Phát triển Nghề nghiệp (IDP) vào Portfolio!', 'success');
}

// Mở Modal Thêm Hội Nghị / Lớp Học
function openAddConferenceModal() {
  const modal = document.getElementById('modal-add-conference');
  if (modal) {
    document.getElementById('conf-input-title').value = '';
    document.getElementById('conf-input-year').value = new Date().getFullYear();
    document.getElementById('conf-input-time').value = `${String(new Date().getMonth() + 1).padStart(2, '0')}/${new Date().getFullYear()}`;
    document.getElementById('conf-input-role').value = 'Học viên hoàn thành';
    document.getElementById('conf-input-org').value = 'Bệnh viện Đại học Y Dược TP.HCM';
    document.getElementById('conf-input-location').value = 'TP. Hồ Chí Minh';
    modal.classList.remove('hidden');
  }
}

// Đóng Modal Thêm Hội Nghị
function closeAddConferenceModal() {
  const modal = document.getElementById('modal-add-conference');
  if (modal) modal.classList.add('hidden');
}

// Lưu Hội Nghị Mới
function saveConference(event) {
  if (event) event.preventDefault();
  const currentUser = APP_STATE.currentUser;
  if (!currentUser) return;

  const title = (document.getElementById('conf-input-title')?.value || '').trim();
  const year = document.getElementById('conf-input-year')?.value || `${new Date().getFullYear()}`;
  const time = document.getElementById('conf-input-time')?.value || `${year}`;
  const role = document.getElementById('conf-input-role')?.value || 'Đại biểu tham dự';
  const org = (document.getElementById('conf-input-org')?.value || 'BV ĐHYD TP.HCM').trim();
  const location = (document.getElementById('conf-input-location')?.value || 'TP.HCM').trim();

  if (!title) {
    showToast('Vui lòng nhập tên hội nghị / lớp học!', 'error');
    return;
  }

  const currentData = getUserDetailedPortfolio(currentUser.id);
  const newConf = { year, time, title, role, org, location, isCustom: true };
  const conferences = [newConf, ...(currentData.conferences || [])];

  saveUserDetailedPortfolio(currentUser.id, { ...currentData, conferences });
  closeAddConferenceModal();
  renderPortfolioTab(currentUser.id);
  showToast(`🎉 Đã thêm hội nghị/lớp học "${title}" vào quá trình đào tạo theo năm!`, 'success');
}

// Xóa Hội Nghị
function deleteConference(index) {
  const currentUser = APP_STATE.currentUser;
  if (!currentUser) return;

  openConfirmModal({
    title: 'Xóa Khóa Học / Hội Nghị',
    icon: '🗑️',
    message: 'Bạn có chắc chắn muốn xóa hội nghị/lớp học này khỏi lịch sử đào tạo?',
    btnText: 'Xác Nhận Xóa',
    btnClass: 'bg-rose-600 hover:bg-rose-700',
    onConfirm: () => {
      const currentData = getUserDetailedPortfolio(currentUser.id);
      const conferences = [...(currentData.conferences || [])];
      conferences.splice(index, 1);
      saveUserDetailedPortfolio(currentUser.id, { ...currentData, conferences });
      renderPortfolioTab(currentUser.id);
      showToast('Đã xóa hội nghị khỏi danh mục.', 'info');
    }
  });
}

