// Tải file Báo Cáo (HTML) để lưu trữ hoặc mở trong Microsoft Word
function downloadDashboardReportHTML() {
  const reportHtml = generateDashboardReportHTML();
  const fullDocument = `
    <!DOCTYPE html>
    <html lang="vi">
    <head>
      <meta charset="UTF-8">
      <title>Bao_Cao_Xep_Bac_Nang_Luc_Dieu_Duong_UMC_2026</title>
      <style>
        body { font-family: 'Times New Roman', Times, serif; margin: 20mm 15mm; background: #fff; }
        @media print { body { margin: 0; } }
      </style>
    </head>
    <body>
      ${reportHtml}
    </body>
    </html>
  `;

  const blob = new Blob([fullDocument], { type: 'text/html;charset=utf-8;' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.setAttribute('download', `Bao_Cao_Xep_Bac_Nang_Luc_Dieu_Duong_UMC_${Date.now()}.html`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  showToast('Đã tải thành công file báo cáo năng lực (có thể mở xem và in trên Word hoặc trình duyệt)!', 'success');
}

