function resetAllSystemDataForDemo() {
  openConfirmModal({
    title: 'Xóa Sạch Dữ Liệu Để Bắt Đầu Demo Mới',
    icon: '🧹',
    message: 'Bạn có chắc chắn muốn <strong>xóa toàn bộ dữ liệu phiếu tự đánh giá, điểm chấm và lịch sử duyệt</strong> để bắt đầu nhập demo từ đầu (0 điểm) không? <br><br><span class="text-xs text-slate-500">Toàn bộ tài khoản và danh mục tiêu chí chuẩn sẽ được giữ nguyên.</span>',
    btnText: 'Xác Nhận Làm Sạch',
    btnClass: 'bg-rose-600 hover:bg-rose-700',
    onConfirm: () => {
      APP_STATE.submissions = [];
      APP_STATE.currentAssessmentScores = {};
      APP_STATE.currentAssessmentOptionKeys = {};
      APP_STATE.currentCriterionEvidences = {};
      
      localStorage.setItem('umc_submissions', JSON.stringify([]));
      localStorage.removeItem('umc_user_portfolios');
      localStorage.removeItem('umc_user_detailed_portfolios');

      // Reset tất cả người dùng về trạng thái chưa có phiếu
      if (Array.isArray(APP_STATE.users)) {
        APP_STATE.users.forEach(u => {
          u.submission = null;
        });
      }

      saveStorage();
      if (typeof renderAssessmentTab === 'function') renderAssessmentTab();
      if (typeof renderApprovalsTab === 'function') renderApprovalsTab();
      if (typeof renderMailboxNotifications === 'function') renderMailboxNotifications();
      if (typeof renderReportsTab === 'function') renderReportsTab();
      if (typeof renderPortfolioTab === 'function') renderPortfolioTab();

      showToast('🧹 Đã làm sạch toàn bộ dữ liệu trên hệ thống! Bạn có thể bắt đầu nhập demo từ đầu.', 'success');
    }
  });
}
window.resetAllSystemDataForDemo = resetAllSystemDataForDemo;


