// TRẠNG THÁI HỒ SƠ, LỜI ĐỘNG VIÊN 4 CẤP, TÍCH HỢP AI & LIÊN KẾT PORTFOLIO
// =========================================================================

// =========================================================================
// HỆ THỐNG DỮ LIỆU GIẢ LẬP DEMO DỰ THI CHO BAN GIÁM KHẢO
// Bao gồm đầy đủ 6 kịch bản hồ sơ từ Tự đánh giá, Chờ duyệt 4 cấp đến Vinh danh
// =========================================================================

function generateRealisticScores(specialty, targetScore) {
  const domains = (typeof DOMAINS_BY_SPECIALTY !== 'undefined' && (DOMAINS_BY_SPECIALTY[specialty] || DOMAINS_BY_SPECIALTY['lamsang'])) || [];
  const scores = {};
  const optionKeys = {};
  const evidences = {};
  const domainScores = {};

  const allCrits = [];
  domains.forEach(d => {
    domainScores[d.id] = 0;
    (d.standards || []).forEach(st => {
      (st.criteria || []).forEach(cr => {
        allCrits.push({ domainId: d.id, crit: cr });
      });
    });
  });

  // Gán điểm chuẩn cho từng tiêu chí
  let currentSum = 0;
  allCrits.forEach(({ crit }) => {
    const opts = crit.options || [];
    if (opts.length > 0) {
      const highest = opts[opts.length - 1];
      scores[crit.id] = highest.score !== undefined ? highest.score : (crit.maxScore || 10);
      optionKeys[crit.id] = highest.level || '';
    } else {
      scores[crit.id] = crit.maxScore || 10;
    }
    currentSum += scores[crit.id];
  });

  // Tinh chỉnh để khớp chính xác targetScore
  let diff = currentSum - targetScore;
  for (let i = allCrits.length - 1; i >= 0 && diff > 0; i--) {
    const { crit } = allCrits[i];
    const opts = crit.options || [];
    if (opts.length > 2 && scores[crit.id] > 5) {
      const nextOpt = opts[opts.length - 2];
      const pointDiff = scores[crit.id] - (nextOpt.score || 0);
      if (pointDiff > 0 && pointDiff <= diff) {
        scores[crit.id] = nextOpt.score || 0;
        optionKeys[crit.id] = nextOpt.level || '';
        diff -= pointDiff;
      }
    }
  }

  // Tính điểm 5 Lĩnh vực
  domains.forEach(d => {
    let dScore = 0;
    (d.standards || []).forEach(st => {
      (st.criteria || []).forEach(cr => {
        dScore += (scores[cr.id] || 0);
      });
    });
    domainScores[d.id] = Math.min(200, Math.max(0, dScore));
  });

  // Đính kèm minh chứng thực tế
  const sampleEvidenceTypes = [
    'Bang_Tot_Nghiep_Dai_Hoc_Y_Duoc_TPHCM.pdf',
    'Chung_Chi_Hanh_Nghe_KCB_So_012892.pdf',
    'Chung_Nhan_CME_An_Toan_Nguoi_Benh_2026.pdf',
    'Bang_Kiem_Quy_Trinh_Tiem_Truyen_An_Toan.pdf',
    'Chung_Nhan_Hoi_Suc_Tim_Phoi_Co_Ban_CPR.pdf',
    'Ke_Hoach_Cham_Soc_Nguoi_Benh_Nang_Khoa_CTCH.pdf',
    'Bien_Ban_Danh_Gia_Su_Hai_Long_Nguoi_Benh.pdf',
    'De_Tai_Nghien_Cuu_Cai_Tien_Chat_Luong_Cham_Soc.pdf',
    'Giay_Khen_Dieu_Duong_Xuat_Sac_UMC_2025.pdf',
    'Chung_Chi_Preceptor_Huong_Dan_Lam_Sang.pdf'
  ];

  allCrits.slice(0, 12).forEach(({ crit }, idx) => {
    const fn = sampleEvidenceTypes[idx % sampleEvidenceTypes.length];
    evidences[crit.id] = [
      {
        id: 'ev_' + crit.id + '_1',
        name: fn,
        size: (1.2 + (idx * 0.1)).toFixed(1) + ' MB',
        date: '10/10/2026',
        type: 'application/pdf',
        verified: true
      }
    ];
  });

  return { scores, optionKeys, domainScores, evidences, totalScore: targetScore };
}

